/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A49 checkpoint staging; frozen manifest hyperbola–ill-equipped, 80 lemmas. */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs});
P('hyperbola','Hyperbola 源自希腊语 hyperbolē“超越、过度”，经拉丁语进入数学术语，指圆锥曲线中有两条分支的双曲线。',C('hyperbola.s1','几何与代数','The graph formed two separate branches, so the mathematician identified the conic section as a hyperbola rather than an ellipse.','图像形成两条分离的分支，因此数学家判断该圆锥曲线是双曲线而不是椭圆。','The graph formed two separate branches / so the mathematician identified the conic section / as a hyperbola rather than an ellipse.','hyperbola 是几何名词；rather than 对比另一种圆锥曲线。','双曲线的图形具有两条分离分支。'),M('The graph was a hyperbola because it formed one closed oval with no separate branches.','The graph was an ellipse because it formed one closed oval with no separate branches.','封闭椭圆不是具有两支的双曲线。'),[Q('hyperbola',1,1,'A hyperbola is a curve that typically has?','two separate branches','one closed circular boundary','three intersecting straight sides','双曲线通常有两条分支。'),Q('hyperbola',2,1,'Which graph is most likely a hyperbola?','a conic curve opening into two disconnected parts','a single oval with no gap','a triangle made from three line segments','两支分离的曲线符合双曲线特征。'),Q('hyperbola',3,1,'Hyperbola belongs to which subject area?','geometry and algebra','botany and mycology','grammar and punctuation','双曲线是数学曲线。'),Q('hyperbola',4,1,'A hyperbola is different from an ellipse because it?','has two open branches instead of one closed oval','is always a circle','contains no curved lines','双曲线分支开放且不形成单一闭环。')]);
P('hyperinflation','Hyperinflation 由 hyper-“过度”与 inflation“通货膨胀”组合，指物价急速上涨、货币购买力严重崩跌的恶性通胀。',C('hyperinflation.s1','经济与货币','During hyperinflation, prices changed so quickly that workers spent their wages the same day to avoid losing purchasing power.','恶性通胀期间物价变化极快，工人当天就花掉工资，以免购买力继续下降。','During hyperinflation / prices changed so quickly / that workers spent their wages the same day / to avoid losing purchasing power.','hyperinflation 是经济名词；so…that 说明物价变化造成的结果。','迅速涨价和货币购买力急跌体现恶性通胀。'),M('The country had hyperinflation because prices and wages remained perfectly stable for decades.','The country had hyperinflation because prices rose rapidly and money lost purchasing power.','长期物价稳定不符合恶性通胀。'),[Q('hyperinflation',1,1,'Hyperinflation is a period when?','prices rise extremely rapidly and money loses value','all prices remain fixed for years','a country removes every coin from circulation','恶性通胀会使物价快速上涨、货币贬值。'),Q('hyperinflation',2,1,'Why might people spend wages quickly during hyperinflation?','their money may buy less if they wait','prices are guaranteed to fall each hour','banks stop allowing any purchases','货币购买力迅速下降会促使尽快消费。'),Q('hyperinflation',3,1,'Which situation suggests hyperinflation?','a loaf of bread costs far more each week','prices stay nearly unchanged for a decade','one store gives a short seasonal discount','物价持续急剧上升是恶性通胀。'),Q('hyperinflation',4,1,'The prefix hyper- in hyperinflation suggests?','an extreme or excessive degree','a reduction to zero','a location beneath the ground','hyper- 表示过度、极端。')]);
P('hyperlink','Hyperlink 是计算机语境中由 hypertext link 缩合而来的词，指可跳转到另一网页、文件或页面位置的链接；也可作动词表示添加链接。',C('hyperlink.s1','网页与导航','The editor added a hyperlink to the source document so readers could open the original study without searching for its title.','编辑添加了指向源文件的超链接，让读者无需搜索标题就能打开原始研究。','The editor added a hyperlink to the source document / so readers could open the original study / without searching for its title.','hyperlink 指可点击的链接；so 引出添加链接的目的。','点击链接即可跳转到源文档，符合定义。'),M('The page contained a hyperlink that could not be clicked and led nowhere because it was plain text.','The page contained a clickable hyperlink that opened the source document.','纯文本不能点击且没有目标，不构成有效超链接。'),[Q('hyperlink',1,1,'A hyperlink on a webpage lets a reader?','jump to another page or resource','change the monitor’s brightness','print a document without a printer','超链接用于跳转到另一资源。'),Q('hyperlink',2,1,'A writer who hyperlinks a phrase has?','attached a clickable link to it','deleted it from the document','translated it into a different language','动词 hyperlink 表示添加链接。'),Q('hyperlink',3,1,'Which item is a hyperlink?','underlined text that opens a cited article when clicked','a heading that cannot be selected','a printed page number with no destination','可点击并打开文章的文字是超链接。'),Q('hyperlink',4,1,'The word hyperlink is associated with?','linked digital text and webpages','a medical eye condition','a curve with two branches','hyperlink 是数字文本链接。')]);
P('hyperopia','Hyperopia 来自希腊语 hyper“远”与 ops“视力”，指远处看得较清楚而近处视物较困难的远视状态。',C('hyperopia.s1','眼科与视力','The optometrist diagnosed hyperopia after the child could read the classroom board clearly but struggled with a nearby book.','孩子能看清教室黑板，却难以看清近处的书；验光师据此诊断为远视。','The optometrist diagnosed hyperopia / after the child could read the classroom board clearly / but struggled with a nearby book.','hyperopia 是视力状况名词；after 引出检查时观察到的表现。','远处清晰、近处困难符合远视特征。'),M('The optometrist diagnosed hyperopia because the patient saw nearby print clearly but could not see distant objects.','The optometrist diagnosed myopia because the patient saw nearby print clearly but could not see distant objects.','远处模糊而近处清楚符合近视，不是远视。'),[Q('hyperopia',1,1,'Hyperopia usually makes it harder to see?','nearby objects clearly','distant mountains clearly','colors in bright sunlight','远视主要影响近距离视物。'),Q('hyperopia',2,1,'A person with hyperopia may read the board but struggle with?','small print held close to the eyes','a distant sign across the street','a large object in the room','近处书本可能难看清。'),Q('hyperopia',3,1,'Hyperopia is a condition of the?','eyes and focusing vision','inner ear and balance','stomach and digestion','hyperopia 是视力问题。'),Q('hyperopia',4,1,'Which pattern is most consistent with hyperopia?','distant vision clearer than near vision','near vision clear but distant vision blurry','no difference in vision at any distance','其典型表现是远处比近处看得清。')]);
P('hypersensitive','Hypersensitive 由 hyper- 与 sensitive 组合，可指对药物或刺激反应过强，也可形容情感上很容易受伤或被冒犯。',C('hypersensitive.s2','人际沟通','After weeks of criticism, Jonah became hypersensitive to even mild comments about his work and assumed each one was an attack.','受到数周批评后，乔纳对别人哪怕轻微的工作意见也格外敏感，总以为每句都是攻击。','After weeks of criticism / Jonah became hypersensitive to even mild comments about his work / and assumed each one was an attack.','hypersensitive 描写情感反应过强；even mild 强调刺激很轻微。','轻微意见也被当作攻击，体现情感敏感义。'),M('The patient was hypersensitive to the medicine because it caused no reaction at any dose.','The patient was hypersensitive to the medicine because a very small dose caused a strong reaction.','完全没有反应与过敏或反应过强相反。'),[Q('hypersensitive',1,1,'A person hypersensitive to a food may?','react unusually strongly to a small amount','eat unlimited amounts without any effect','avoid noticing the food’s taste','hypersensitive 可指对食物过度反应。'),Q('hypersensitive',2,2,'Someone emotionally hypersensitive may be?','easily hurt or offended by mild comments','unable to feel any emotion','always certain that criticism is praise','此词也可描述情感上容易受伤。'),Q('hypersensitive',3,1,'Which response suggests hypersensitivity to criticism?','treating a gentle suggestion as a personal attack','considering feedback calmly','asking what a reviewer meant','把温和建议视为攻击体现反应过度。'),Q('hypersensitive',4,1,'The prefix hyper- in hypersensitive signals?','an unusually high degree of sensitivity','a lack of any sensitivity','a medical location under the skin','hyper- 表示程度过高。')]);
P('hypertext','Hypertext 是计算机领域用语，指带有链接、可让读者跳转阅读而非只按线性顺序浏览的文本。',C('hypertext.s1','数字阅读','The archive stores its articles as hypertext, allowing readers to follow links from a person’s name to related letters and photographs.','档案馆把文章存为超文本，读者可从人名链接跳转到相关信件和照片。','The archive stores its articles as hypertext / allowing readers to follow links / from a person’s name to related letters and photographs.','hypertext 指含可跳转链接的文本；allowing 说明其阅读功能。','链接使读者可在关联材料之间跳转。'),M('The archive called its text hypertext although every page was isolated and offered no links.','The archive used hypertext with links connecting articles to related records.','完全孤立且没有链接的文本不符合超文本的特点。'),[Q('hypertext',1,1,'Hypertext differs from plain linear text because readers can?','jump between linked sections or resources','only read one printed page ever','change the language of every word automatically','超文本允许通过链接跳转。'),Q('hypertext',2,1,'A digital archive uses hypertext when it?','links names and topics to related records','prints every document without cross-references','stores only photographs with no text','链接文字与关联记录构成超文本。'),Q('hypertext',3,1,'Hypertext is most closely associated with?','linked digital documents','traditional unlinked paper rolls only','a curve in algebra','超文本是数字文档结构。'),Q('hypertext',4,1,'The element text in hypertext refers to?','written content readers can navigate','a type of eye lens','a fungal cell filament','hypertext 中 text 指文本。')]);
P('hypha','Hypha 源自希腊语 hyphē“网、织物”，生物学中指真菌体内细长、可分枝的菌丝。',C('hypha.s1','真菌学','Under the microscope, one hypha extended through the damp soil and branched into several fine fungal threads.','显微镜下，一条菌丝穿过潮湿土壤，并分出几条细小的真菌丝。','Under the microscope / one hypha extended through the damp soil / and branched into several fine fungal threads.','hypha 是单数名词，复数形式常为 hyphae；and 连接菌丝延伸与分枝。','细长并分枝的真菌丝符合 hypha 定义。'),M('The biologist called a single round animal cell a hypha even though it had no filament or branches.','The biologist called the long branching fungal filament a hypha.','圆形动物细胞不是细长分枝的真菌菌丝。'),[Q('hypha',1,1,'A hypha is a?','long branching filament of fungal cells','single red blood cell','hard mineral crystal','hypha 指真菌菌丝。'),Q('hypha',2,1,'Many hyphae together form much of a?','fungus’s growing body','mammal’s skeleton','flower’s outer petals','菌丝共同构成真菌体的大部分。'),Q('hypha',3,1,'Which feature is typical of a hypha?','a threadlike form that can branch','a flat leaf with a central vein','a hollow bone with a joint','菌丝细长且可能分枝。'),Q('hypha',4,1,'Hypha is most likely discussed in?','mycology, the study of fungi','astronomy, the study of stars','geometry, the study of curves','hypha 是真菌学术语。')]);
P('hyphen','Hyphen 经拉丁语从希腊语 hyphen“连在一起”进入英语；名词指连接词语部分的短横线，也可作动词表示用连字符连接。',C('hyphen.s2','编辑与排版','The copy editor hyphenated “well-known” to show that the two words function together before the noun.','文字编辑在“well-known”中加了连字符，表示两个词在名词前共同发挥作用。','The copy editor hyphenated “well-known” / to show that the two words function together / before the noun.','hyphen 作动词表示加连字符；to show 引出标点的作用。','编辑将两个词连接起来，体现动词义。'),M('The editor hyphenated the phrase by inserting a comma between the two parts.','The editor hyphenated the phrase by inserting a short dash between its two parts.','逗号不是连字符。'),[Q('hyphen',1,1,'A hyphen is the short mark used to?','join parts of a word or expression','end every question','separate two paragraphs with a blank page','hyphen 指连字符。'),Q('hyphen',2,2,'To hyphenate “well known” in a compound modifier is to?','write it as “well-known”','replace it with a question mark','remove both words','动词 hyphenate 表示加连字符。'),Q('hyphen',3,1,'Which mark is a hyphen?','the short line in “part-time”','the comma after a greeting','the period ending a sentence','part-time 中间的短横线是连字符。'),Q('hyphen',4,1,'The Greek source of hyphen relates to putting things?','together','under the ground','far away from one another','词源义与连接在一起有关。')]);
P('hypnosis','Hypnosis 源自希腊语 hypnos“睡眠”，指由暗示诱导出的恍惚状态或催眠过程。',C('hypnosis.s1','心理与临床','During hypnosis, the trained clinician asked the volunteer to focus on a steady voice while remaining aware of the room.','在催眠过程中，受训的临床人员请志愿者专注于平稳的声音，同时仍意识到周围环境。','During hypnosis / the trained clinician asked the volunteer / to focus on a steady voice / while remaining aware of the room.','hypnosis 指催眠状态或过程；while 从句说明注意状态。','注意集中、受暗示影响的状态符合 hypnosis。'),M('The clinician described hypnosis as ordinary sleep in which the volunteer could not hear or respond at all.','The clinician described hypnosis as a focused trance in which the volunteer could still respond.','催眠不等同于完全失去意识的普通睡眠。'),[Q('hypnosis',1,1,'Hypnosis is a state in which a person may?','enter a focused trance and respond to suggestion','lose all brain activity permanently','become unable to hear any sound','hypnosis 指可受暗示影响的恍惚状态。'),Q('hypnosis',2,1,'A hypnosis session is usually induced through?','focused attention and suggestion','a sudden physical injury','a mathematical graph','催眠通常依靠集中注意和暗示。'),Q('hypnosis',3,1,'Hypnosis is related to the Greek word for?','sleep','fire','honey','hypnos 意为睡眠。'),Q('hypnosis',4,1,'Which is a careful description of hypnosis?','a trance-like focused state, not simply ordinary sleep','a permanent loss of consciousness','a guaranteed way to control every person','催眠是恍惚专注状态，不是普通睡眠。')]);
P('hypnotic','Hypnotic 源自希腊语 hypnos“睡眠”，作形容词表示催眠的、令人沉睡或着迷的，也可作名词指催眠药。',C('hypnotic.s1','声音与注意','The hypnotic rhythm of the rain on the roof held the campers’ attention until several of them drifted to sleep.','雨滴敲打屋顶的催眠节奏吸引了露营者的注意，直到几个人渐渐睡着。','The hypnotic rhythm of the rain on the roof / held the campers’ attention / until several of them drifted to sleep.','hypnotic 修饰 rhythm，表示使人入神或昏昏欲睡。','稳定重复的雨声使人专注并入睡，符合形容词义。'),M('The doctor called a medicine hypnotic even though it was prescribed to keep patients awake all night.','The doctor called the sleep-inducing medicine a hypnotic.','使人保持清醒的药与催眠药作用相反。'),[Q('hypnotic',1,1,'A hypnotic rhythm may?','make listeners feel sleepy or deeply absorbed','make every listener run faster','prevent anyone from hearing it','形容词 hypnotic 可使人昏昏欲睡或着迷。'),Q('hypnotic',2,2,'A hypnotic prescribed by a doctor is a?','drug used to induce sleep','medicine that always prevents sleep','device for testing eyesight','hypnotic 作名词指催眠药。'),Q('hypnotic',3,1,'A hypnotic view is likely to be?','so fascinating that it holds attention','too plain to notice','dangerous because it contains ice','也可形容令人着迷的景象。'),Q('hypnotic',4,2,'Which sentence uses hypnotic as a noun?','The physician prescribed a hypnotic for short-term insomnia.','The hypnotic music played softly.','The view had a hypnotic effect.','此句中 hypnotic 直接指药物。')]);
P('hypnotise','Hypnotise 是英式拼写，源自 hypnosis 加动词后缀 -ise，指通过暗示使人进入催眠状态，也可比喻使人全神贯注。',C('hypnotise.s2','专注与吸引','The documentary’s vivid images hypnotised the audience, who barely noticed that the screening had run past midnight.','纪录片生动的画面让观众看得入迷，几乎没注意到放映已过午夜。','The documentary’s vivid images hypnotised the audience / who barely noticed / that the screening had run past midnight.','hypnotise 作比喻动词表示完全吸引注意；who 从句展示其效果。','观众沉浸其中而忽略时间，体现使着迷义。'),M('The presenter hypnotised the audience by showing nothing and holding no one’s attention.','The presenter hypnotised the audience with a compelling demonstration that held their attention.','完全没有吸引注意与 hypnotise 的比喻义相反。'),[Q('hypnotise',1,1,'To hypnotise a volunteer is to?','induce a trance through suggestion','give them an eye examination','teach them how to spell a word','hypnotise 指施行催眠。'),Q('hypnotise',2,2,'A spectacular performance can hypnotise viewers by?','holding their attention completely','making them leave before it begins','preventing them from seeing the stage','比喻义表示使人着迷。'),Q('hypnotise',3,1,'Which spelling is the British form?','hypnotise','hypnotize','hypnotiz','题目要求保留英式 -ise 拼法。'),Q('hypnotise',4,2,'A hypnotised audience might?','be so absorbed that they lose track of time','ignore the performance from the start','watch only the exit signs','入迷的观众可能忘记时间。')]);
P('hypocrisy','Hypocrisy 源自希腊语 hypokrisis，原指表演或扮演，后指假装自己比实际更道德，也可指一次虚伪行为。',C('hypocrisy.s2','言行一致','The mayor’s public speech against favoritism looked like hypocrisy when records showed that she had given contracts to her relatives.','记录显示市长把合同给了亲属后，她公开反对偏袒的讲话显得很虚伪。','The mayor’s public speech against favoritism / looked like hypocrisy / when records showed that she had given contracts to her relatives.','hypocrisy 作名词指伪善；when 从句揭示言行不一的证据。','公开标准与私下行为矛盾，构成伪善。'),M('The report called her honesty hypocrisy even though she followed the same rule she asked others to follow.','The report called her conduct hypocrisy because she broke the rule she publicly demanded others follow.','一贯遵守自己倡导的规则不是伪善。'),[Q('hypocrisy',1,1,'Hypocrisy is?','pretending to follow standards one does not actually follow','openly admitting a mistake','a scientific explanation awaiting a test','hypocrisy 指假装遵守自己并不实行的标准。'),Q('hypocrisy',2,2,'A single act of hypocrisy is?','one instance of such pretence','a permanently honest choice','a harmless weather change','名词也可指一次虚伪行为。'),Q('hypocrisy',3,1,'Why was the speech called hypocrisy?','the speaker secretly did what she condemned','the speaker followed her stated rule','the speaker refused to discuss the issue','谴责某行为却自己去做是言行不一。'),Q('hypocrisy',4,1,'The Greek source of hypocrisy once referred to?','acting or performance','a fungal filament','a mountain goat','词源与表演、扮演有关。')]);
P('hypocritical','Hypocritical 由 hypocrisy 加 -ical 构成，形容表面宣称遵守某种标准、实际却不按标准行事。',C('hypocritical.s1','职业操守','It was hypocritical for the manager to demand punctuality from staff while arriving late to every weekly meeting.','经理每周开会都迟到，却要求员工守时，这种做法很虚伪。','It was hypocritical for the manager to demand punctuality / while arriving late / to every weekly meeting.','hypocritical 描写要求与自身行为不一致；while 引出矛盾行为。','管理者不遵守自己要求的标准，体现 hypocritical。'),M('Her fair decision was hypocritical because she applied the same rule to herself and to everyone else.','Her decision was consistent because she applied the same rule to herself and everyone else.','公平一致地执行规则与伪善相反。'),[Q('hypocritical',1,1,'A hypocritical person?','claims a standard but does not follow it themselves','consistently follows the same rule they support','admits openly that they changed their mind','hypocritical 指言行不一。'),Q('hypocritical',2,1,'Which action is hypocritical?','a leader condemns nepotism but hires relatives secretly','a leader applies the same hiring rules to everyone','a leader admits a conflict of interest','私下偏袒亲属却公开反对是伪善。'),Q('hypocritical',3,1,'Hypocritical is an adjective related to?','hypocrisy','hypothesis','hyperbola','hypocritical 与 hypocrisy 同源。'),Q('hypocritical',4,1,'Why might a promise be called hypocritical?','the speaker’s actions contradict the promised standard','the speaker keeps the promise consistently','the promise is written in clear language','行动与承诺标准相反会显得虚伪。')]);
P('hypothalamus','Hypothalamus 由 hypo-“下方”与 thalamus 构成，指丘脑下方调节体温、饥饿、激素等基本功能的脑区。',C('hypothalamus.s1','神经科学','The hypothalamus helps regulate body temperature, so it triggers responses such as sweating when the body gets too warm.','下丘脑帮助调节体温，因此身体过热时会触发出汗等反应。','The hypothalamus helps regulate body temperature / so it triggers responses / such as sweating when the body gets too warm.','hypothalamus 是脑区名词；so 引出调节功能带来的反应。','体温调节和出汗反应对应下丘脑功能。'),M('The neurologist located the hypothalamus in the foot because it controls sweating and hunger.','The neurologist located the hypothalamus in the brain because it helps regulate body functions.','下丘脑是脑区，不在足部。'),[Q('hypothalamus',1,1,'The hypothalamus is a region of the?','brain','stomach','lower leg','hypothalamus 是脑区。'),Q('hypothalamus',2,1,'One function of the hypothalamus is helping regulate?','temperature and other basic body functions','the spelling of medical words','the movement of planets','它参与调节体温等基本功能。'),Q('hypothalamus',3,1,'When the body becomes too warm, the hypothalamus can help trigger?','sweating','a change in eye color','the growth of a new limb','下丘脑可触发出汗调温。'),Q('hypothalamus',4,1,'The prefix hypo- in hypothalamus means?','under or below','above or beyond','equal in size','hypo- 表示下方。')]);
P('hypothesis','Hypothesis 源自希腊语 hypothesis“提出的基础、假定”，指可检验的解释或为讨论而暂时接受的前提。',C('hypothesis.s1','科学研究','The researchers tested the hypothesis that cooler water would slow the algae’s growth by repeating the trial at three temperatures.','研究人员在三种温度下重复实验，以检验“较冷的水会减缓藻类生长”这一假说。','The researchers tested the hypothesis / that cooler water would slow the algae’s growth / by repeating the trial at three temperatures.','hypothesis 是待检验的解释；that 从句具体陈述假说内容。','研究者通过实验验证假设，符合科学义。'),M('The team treated its hypothesis as proven fact before collecting any observations.','The team treated its hypothesis as an explanation to test with observations.','未经观察检验的假设不能直接视作已证实事实。'),[Q('hypothesis',1,1,'A scientific hypothesis is an idea that?','can be tested as a possible explanation','is accepted as true without evidence','cannot be examined by observation','假说是可检验的可能解释。'),Q('hypothesis',2,2,'In an argument, a hypothesis may be?','a statement temporarily assumed for discussion','the final proof of every claim','a tool used to measure temperature','hypothesis 也可指讨论前提。'),Q('hypothesis',3,1,'What should researchers do with a hypothesis?','test it against evidence','hide it from all observations','treat it as correct before testing','研究者应通过证据检验假说。'),Q('hypothesis',4,1,'A hypothesis differs from a confirmed result because it?','still needs testing','can never be changed','is always a mathematical identity','假说尚待验证。')]);
P('hypothesize','Hypothesize 由 hypothesis 加 -ize 构成，表示根据现象提出一个有待检验的解释或假说。',C('hypothesize.s1','科学推理','From the unusual tracks, the biologists hypothesized that a larger animal had visited the pond at night.','生物学家根据异常足迹提出假设：夜间有一只更大的动物到过池塘。','From the unusual tracks / the biologists hypothesized / that a larger animal had visited the pond at night.','hypothesize 是及物动词；that 从句给出提出的假说。','从观察到的足迹推测可能原因，符合提出假设。'),M('The biologists hypothesized the animal’s visit by proving it beyond doubt before examining the tracks.','The biologists hypothesized the animal’s visit from the tracks and planned to test the idea.','hypothesize 表示提出待检验解释，不是先行确证。'),[Q('hypothesize',1,1,'To hypothesize is to?','propose a possible explanation to be tested','declare a guess permanently proven','ignore all observations','hypothesize 指提出可检验假设。'),Q('hypothesize',2,1,'Scientists might hypothesize that a plant grows faster because?','they have observations suggesting a possible cause','they refuse to conduct any test','the result is already certain without evidence','假说源于观察但仍需测试。'),Q('hypothesize',3,1,'Which verb is closest to hypothesize?','propose a tentative explanation','confirm beyond all doubt','erase from the record','hypothesize 最接近提出暂定解释。'),Q('hypothesize',4,1,'After researchers hypothesize, they should usually?','design a test of the proposed explanation','stop collecting data forever','treat every alternative as impossible','之后通常需要设计检验。')]);
P('hypothetical','Hypothetical 由 hypothesis 加 -ical 构成，形容为了讨论可能性而设想的、尚非已知事实的情形。',C('hypothetical.s1','情境讨论','The lawyer posed a hypothetical case about a lost passport to explain how the new travel rule might work.','律师提出一个关于护照遗失的假设案例，解释新旅行规定可能如何适用。','The lawyer posed a hypothetical case about a lost passport / to explain / how the new travel rule might work.','hypothetical 修饰 case，说明案例是假定情境而非真实案件。','为了讨论规则而设想情境，符合词义。'),M('The lawyer called the ongoing real trial hypothetical even though witnesses were testifying in court.','The lawyer presented a hypothetical case to discuss a situation that had not actually occurred.','正在开庭且有证人作证的真实案件不是假设情境。'),[Q('hypothetical',1,1,'A hypothetical situation is?','imagined for discussion rather than known to be real','a documented event that definitely happened','a physical object used in an experiment','hypothetical 指假想情形。'),Q('hypothetical',2,1,'A teacher asks a hypothetical question to?','explore what might happen under an imagined condition','record a fact already verified','prevent students from considering possibilities','假设问题用于讨论可能性。'),Q('hypothetical',3,1,'Which case is hypothetical?','a made-up example about a passport that has not been lost','a verified court case with named witnesses','an actual travel delay recorded yesterday','未发生的护照遗失案例是假设。'),Q('hypothetical',4,1,'Hypothetical is related to the noun?','hypothesis','hypnosis','honeycomb','hypothetical 与 hypothesis 同源。')]);
P('hysterical','Hysterical 源自 hysteria 一类旧医学词；现代常指情绪失控，也可口语表示极其好笑，医学用法多被视为过时或需谨慎。',C('hysterical.s2','幽默与反应','The audience found the comedian’s story hysterical and laughed so loudly that the next act paused backstage.','观众觉得喜剧演员的故事极其好笑，笑声太大，以致下一位演员在后台暂停等候。','The audience found the comedian’s story hysterical / and laughed so loudly / that the next act paused backstage.','hysterical 在口语中可表示非常好笑；found + 宾语 + 形容词说明评价。','观众大笑并打断演出，体现“极其滑稽”义。'),M('The comic’s story was hysterical because nobody laughed and the audience found it painfully dull.','The comic’s story was hysterical because the audience laughed throughout.','观众觉得乏味且无人发笑，与口语义相反。'),[Q('hysterical',1,1,'A hysterical person in the emotional sense may be?','unable to control intense crying or laughter','calmly explaining a routine schedule','unaware that anyone is speaking','该义指情绪强烈且难控制。'),Q('hysterical',2,2,'In casual speech, a hysterical story is?','extremely funny','medically diagnosed in every case','too quiet to understand','口语义可指极其好笑。'),Q('hysterical',3,3,'Why should the medical use of hysterical be handled carefully?','it comes from an outdated diagnostic tradition','it is a neutral name for every emotion','it always means a humorous story','旧医学用法有过时背景，需谨慎。'),Q('hysterical',4,1,'Which reaction sounds hysterical in the emotional sense?','someone sobbing and laughing uncontrollably','someone calmly taking notes','someone quietly reading a map','无法控制的哭笑符合情绪义。')]);
P('I','I 源自古英语第一人称代词 ic；现代英语中作主格时必须大写，通常在句中作说话者主语。',C('I.s1','英语语法','When the teacher asked who had finished the chart, I raised my hand and said that I was ready to present it.','老师问谁完成了图表时，我举手说自己已准备好展示。','When the teacher asked who had finished the chart / I raised my hand / and said that I was ready to present it.','I 是第一人称单数主格代词；英语中无论在句中何处都大写。','I 作说话者主语并保持大写。'),M('Me finished the chart, and the teacher asked me to present it.','I finished the chart, and the teacher asked me to present it.','句中作主语应用主格 I，而不是宾格 me。','grammar'),[Q('I',1,1,'Which pronoun does a speaker use for themself as the subject?','I','me','mine','主语位置用 I。'),Q('I',2,1,'How is the first-person singular pronoun written in English?','with a capital letter: I','always as a lowercase i','as a plural word: we','第一人称 I 始终大写。'),Q('I',3,1,'Choose the grammatical sentence.','I saw the comet last night.','Me saw the comet last night.','Mine saw the comet last night.','动词 saw 前的主语代词应为 I。'),Q('I',4,1,'In “Maya and I arrived,” I is?','part of the subject','the object of a preposition','a possessive adjective','Maya and I 是复合主语。')]);
P('ibex','Ibex 经拉丁语进入英语，源头可能是阿尔卑斯地区的古名，指欧洲、亚洲或非洲山区长有粗大棱角的野山羊。',C('ibex.s1','高山野生动物','A male ibex climbed a narrow ledge above the valley, balancing carefully on its hooves beneath its heavy ridged horns.','一只雄性北山羊在山谷上方的窄岩架上攀爬，粗大的棱纹犄角下，它用蹄子小心保持平衡。','A male ibex climbed a narrow ledge above the valley / balancing carefully on its hooves / beneath its heavy ridged horns.','ibex 指山地野山羊；beneath 短语补充动物角部特征。','高山栖息、攀岩与粗大棱角符合羱羊特征。'),M('The guide identified the hornless seabird swimming offshore as an ibex.','The guide identified the mountain goat with heavy ridged horns as an ibex.','海鸟不是长有粗大棱角的山地野山羊。'),[Q('ibex',1,1,'An ibex is a kind of?','wild mountain goat with ridged horns','large seabird with a hooked beak','small fish living under ice','ibex 指北山羊或羱羊。'),Q('ibex',2,1,'Where would an ibex most likely live?','rocky mountain slopes','a coral reef','a tropical rainforest canopy','羱羊常生活在山区。'),Q('ibex',3,1,'Which feature helps identify an ibex?','heavy horns with ridges','feathers covering its forelegs','a flat shell on its back','棱纹粗角是显著特征。'),Q('ibex',4,1,'The plural of ibex can remain?','ibex','ibexes only, never ibex','ibices only','ibex 的复数可与单数同形。')]);
P('ice','Ice 源自古英语 īs，名词指冻结的水或饮料中的冰块；作动词可指结冰、使结冰、给饮料加冰或给蛋糕涂糖霜。',C('ice.s4','饮品与烘焙','The café iced the lemonade before serving it and piped white icing onto the birthday cake.','咖啡馆在端上柠檬水前加了冰，并在生日蛋糕上挤上白色糖霜。','The café iced the lemonade / before serving it / and piped white icing onto the birthday cake.','ice 作动词可表示给饮料加冰或为蛋糕覆糖霜。','句子分别展示饮品冰镇和蛋糕装饰两种动词用法。'),M('The baker iced the cake by leaving it plain with no frosting or decoration.','The baker iced the cake with a smooth layer of frosting.','没有糖霜的原样蛋糕不是被 icing 过的蛋糕。'),[Q('ice',1,1,'Ice in its basic sense is?','water that has frozen solid','water vapor in warm air','a sweet syrup poured on bread','ice 的基本义是固态水。'),Q('ice',2,2,'A customer asks for ice in a drink when they want?','frozen water cubes added to it','the drink heated until boiling','a new glass with no liquid','饮料中的 ice 是冰块。'),Q('ice',3,3,'If a pond ices over, it?','becomes covered with ice','turns into a sandy beach','dries up instantly','ice 作动词可表示结冰。'),Q('ice',4,4,'To ice a cake is to?','cover it with icing or frosting','freeze the oven solid','remove every topping from it','ice 作动词可指给蛋糕涂糖霜。')]);
P('ice-cream','Ice-cream 由 ice 与 cream 组合，指以奶油或牛奶制成的甜味冷冻甜点，也可指一份冰淇淋。',C('ice-cream.s2','甜点与分量','After dinner, each child chose one ice-cream in a paper cup, and the server added a spoonful of berries.','晚饭后，每个孩子都选了一份杯装冰淇淋，服务员又添了一勺浆果。','After dinner / each child chose one ice-cream in a paper cup / and the server added a spoonful of berries.','ice-cream 可按份数作可数名词；one 指一份。','每个孩子领取一份，体现 portion 义。'),M('The menu offered one ice-cream for each guest but served them only as hot soup.','The menu offered one ice-cream for each guest and served it frozen.','冰淇淋是冷冻甜点，不是热汤。'),[Q('ice-cream',1,1,'Ice-cream is a sweet frozen dessert usually made with?','cream or milk','dry hay and salt','hot coffee beans only','冰淇淋通常以奶或奶油制成。'),Q('ice-cream',2,2,'At a café, “two ice-creams” can mean?','two servings of the dessert','two freezers in the kitchen','two cartons of warm milk','复数可表示两份冰淇淋。'),Q('ice-cream',3,1,'Which dish is ice-cream?','a frozen vanilla dessert in a cone','a hot vegetable broth','a slice of dry toast','冷冻香草甜点是冰淇淋。'),Q('ice-cream',4,1,'Ice-cream is normally served?','cold or frozen','boiling hot','as a dry powder with no liquid history','冰淇淋通常冷冻食用。')]);
P('iceberg','Iceberg 经荷兰语 ijsberg“冰山”进入英语，指海上漂浮的大块冰，也可比喻表面可见部分很小而隐情更大的问题。',C('iceberg.s2','问题分析','The first audit found only two missing receipts, but the finance director warned that they might be the tip of the iceberg.','第一次审计只发现两张收据缺失，但财务主管警告说这可能只是冰山一角。','The first audit found only two missing receipts / but the finance director warned / that they might be the tip of the iceberg.','tip of the iceberg 是固定比喻，指可见问题背后还有更大部分。','少量发现可能暗示更大范围的财务问题。'),M('The two missing receipts were the tip of the iceberg because the audit confirmed there were no other problems.','The two missing receipts were the tip of the iceberg because later checks found widespread missing records.','若已确认没有其他问题，就不能说它只是更大问题的表面部分。'),[Q('iceberg',1,1,'An iceberg is a?','large mass of floating ice, mostly below the water','small frozen puddle on a sidewalk','rock formation on a hot desert plain','冰山大部分隐藏在水面下。'),Q('iceberg',2,2,'“The tip of the iceberg” means?','a small visible part of a much larger hidden problem','the largest part of an issue already resolved','a harmless piece of frozen water','习语比喻可见部分只占整体很小一部分。'),Q('iceberg',3,1,'Why can an iceberg be dangerous to ships?','most of its mass lies under the water','it melts instantly in cold seas','it is always smaller than a boat','水下主体不易看见，船只可能撞上。'),Q('iceberg',4,2,'If new evidence reveals a bigger scandal, the first report may have been?','only the tip of the iceberg','the whole iceberg in every detail','a harmless icebox','初始发现可能只是问题的一角。')]);
P('icebox','Icebox 由 ice 与 box 组合，指过去放入冰块以保存食物的保冷箱或老式冰箱。',C('icebox.s1','家用器具史','Before electric refrigerators became common, the grocer delivered a block of ice for the family’s wooden icebox.','电冰箱普及之前，杂货店会送来一块冰，供这家人放进木制冰箱。','Before electric refrigerators became common / the grocer delivered a block of ice / for the family’s wooden icebox.','icebox 指靠冰块制冷的旧式储食容器。','木箱需定期加入冰块来保持低温。'),M('The old icebox cooled food with a powerful electric compressor and never needed ice.','The old icebox cooled food with a block of ice placed inside.','靠压缩机而不需冰块的是现代电冰箱。'),[Q('icebox',1,1,'An old-fashioned icebox kept food cool using?','a block of ice inside the container','a gas burner under the shelves','a fan that produced snow','旧式冰箱靠冰块制冷。'),Q('icebox',2,1,'Before electric fridges, families used an icebox to?','store perishable food at a low temperature','freeze a lake for skating','heat meals in a metal oven','冰箱用于低温保存食物。'),Q('icebox',3,1,'Which detail identifies an icebox?','someone periodically replaces its melting ice','it contains a modern compressor only','it has no insulated walls or cooling source','需补充冰块是冰盒的特征。'),Q('icebox',4,1,'Icebox is a compound of ice and?','box','cap','cream','icebox 由 ice 与 box 组成。')]);
P('icecap','Icecap 由 ice 与 cap 组合，指覆盖陆地高处或大片区域的厚冰盖。',C('icecap.s1','冰川地貌','Satellite images showed that the island’s icecap had shrunk over the decade, exposing dark rock along the coast.','卫星图像显示，这座岛的冰盖十年间缩小了，海岸边露出深色岩石。','Satellite images showed / that the island’s icecap had shrunk over the decade / exposing dark rock along the coast.','icecap 指覆盖陆地的厚冰层；that 从句报告冰盖变化。','大面积冰层融退并露出岩石，符合冰盖概念。'),M('The geologist called a warm sandy beach an icecap although no thick ice covered the land.','The geologist called the thick sheet of ice covering the plateau an icecap.','没有厚冰覆盖的海滩不是冰盖。'),[Q('icecap',1,1,'An icecap is?','a thick covering of ice over land','a thin drink cube in a glass','a pointed icicle hanging from a roof','icecap 指陆地上的大片厚冰。'),Q('icecap',2,1,'An icecap may shrink when?','more ice melts than is added','the region becomes permanently colder','the ice turns into solid rock without melting','净融化会使冰盖缩小。'),Q('icecap',3,1,'Which feature could be an icecap?','a broad sheet of ice over a high island','one small cube in a lemonade','a snowball held in a hand','覆盖大片陆地的冰层是冰盖。'),Q('icecap',4,1,'The word cap suggests that the ice?','covers or tops an area of land','is a kind of frozen dessert','hangs down as a narrow point','冰盖覆盖在陆地表面。')]);
P('ichthyosaur','Ichthyosaur 由希腊语 ichthys“鱼”与 sauros“蜥蜴”构成，指外形似鱼、生活于海中的史前爬行动物。',C('ichthyosaur.s1','古生物学','The fossil of an ichthyosaur showed flippers and a long snout, adaptations that helped the ancient reptile swim.','鱼龙化石显示它有鳍肢和长吻，这些特征帮助这种古代爬行动物游泳。','The fossil of an ichthyosaur showed flippers and a long snout / adaptations / that helped the ancient reptile swim.','ichthyosaur 指史前海生爬行动物；that 从句说明身体结构的作用。','鳍肢、长吻和海中生活符合鱼龙特征。'),M('The museum labeled a living freshwater trout an ichthyosaur because both animals swim.','The museum labeled the fossilized marine reptile with flippers an ichthyosaur.','现生鱼类不是史前海生爬行动物。'),[Q('ichthyosaur',1,1,'An ichthyosaur was a prehistoric?','marine reptile with a fishlike body','modern bird with feathered wings','land mammal that lived in caves','鱼龙是史前海生爬行动物。'),Q('ichthyosaur',2,1,'Which fossil might belong to an ichthyosaur?','a long-snouted reptile with flippers','a flowering plant with roots','a modern fish with no fossil record','鱼龙有鳍肢和长吻。'),Q('ichthyosaur',3,1,'The Greek element ichthys means?','fish','ice','image','ichthys 表示鱼。'),Q('ichthyosaur',4,1,'An ichthyosaur lived primarily?','in prehistoric seas','in a modern city park','inside a beehive','鱼龙生活于史前海洋。')]);
P('icicle','Icicle 源自古英语 īs-gicel 一类“冰的冰柱”复合形式，指从屋檐、树枝等处垂下的尖长冰柱。',C('icicle.s1','冬季观察','A clear icicle hung from the cabin roof after the afternoon thaw refroze overnight.','午后融化的水夜间重新冻住后，一根透明冰柱挂在小屋屋檐上。','A clear icicle hung from the cabin roof / after the afternoon thaw / refroze overnight.','icicle 是从高处垂下的尖状冰体；after 从句交代形成过程。','融水从屋檐滴落并重新冻结，形成冰柱。'),M('The icicle grew upward from the warm floor and remained liquid in the freezing air.','The icicle formed downward from the cold roof as dripping water froze.','冰柱通常向下垂挂，液态水也不会在冰冷空气中保持不冻。'),[Q('icicle',1,1,'An icicle is a pointed piece of ice that?','hangs from a roof, branch, or similar surface','floats as a large mass in the sea','is served in a paper cup','icicle 指垂挂的冰柱。'),Q('icicle',2,1,'How can an icicle form on a roof?','dripping water freezes as it hangs down','warm air melts a rock into a point','snow is packed into a ball','屋檐滴水冻结可形成冰柱。'),Q('icicle',3,1,'Which object is an icicle?','a narrow spike of ice under an eave','a broad sheet of ice covering land','a frozen dessert made with cream','屋檐下尖长冰体是 icicle。'),Q('icicle',4,1,'The suffix-like element -icle often suggests?','a small thing or form','a large mountain range','a person who speaks','icicle 指细小尖状的冰体。')]);
P('icon','Icon 源自希腊语 eikōn“图像”，可指电脑界面图标、受崇敬的标志性人物，也可指东正教用于礼拜的圣像。',C('icon.s1','软件界面','Click the folder icon to open the archive, then drag the selected files into the project window.','点击文件夹图标打开档案，再把选中的文件拖进项目窗口。','Click the folder icon / to open the archive / then drag the selected files into the project window.','icon 指代表程序或文件的小型界面符号；to open 说明点击后的功能。','文件夹符号代表档案位置，属于电脑图标义。'),M('The desktop icon was a full printed manual weighing several kilograms on the screen.','The desktop icon was a small symbol that opened the manual file when clicked.','界面 icon 是小型符号，不是屏幕上实体的厚重手册。'),[Q('icon',1,1,'A desktop icon is a small symbol that?','represents a program, file, or action','measures the computer’s temperature','prints a book by itself','电脑 icon 代表程序或文件。'),Q('icon',2,2,'A pop singer described as an icon is?','greatly admired as a symbol of a style or era','a tiny image used only to open a folder','a religious painting kept for worship','icon 也可指受崇敬的代表人物。'),Q('icon',3,3,'An Orthodox icon is a?','painting of a holy person used in worship','computer symbol for a document','famous athlete who represents a decade','宗教圣像用于礼拜。'),Q('icon',4,1,'Which use of icon is digital?','clicking the settings symbol on a screen','hanging a sacred painting in a church','calling a singer a cultural icon','屏幕上的设置符号是数字图标。')]);
P('iconic','Iconic 由 icon 加 -ic 构成，形容广为认作某时代、地点或风格象征的事物，也可表示以图像符号表达的。',C('iconic.s2','视觉符号','The map used an iconic symbol of a tree to mark every campsite, making the locations easy to recognize.','地图用树的图像符号标出每个营地，让这些地点容易辨认。','The map used an iconic symbol of a tree / to mark every campsite / making the locations easy to recognize.','iconic 在此表示用图像符号呈现；to mark 说明符号用途。','树形图像代表营地位置，体现图像符号义。'),M('The map used an iconic symbol that had no visual resemblance or agreed meaning for any reader.','The map used an iconic tree symbol that readers could recognize as a campsite marker.','毫无图像或公认含义的标记不符合此处 iconic。'),[Q('iconic',1,1,'An iconic building is one that?','is widely recognized as a symbol of a place or style','is hidden from public view','has no features people remember','iconic 常指具有代表性的建筑。'),Q('iconic',2,2,'An iconic sign in art uses?','a recognizable pictorial symbol','a random sound with no image','a chemical formula only','iconic 也指图像符号的。'),Q('iconic',3,1,'Which object is likely iconic?','a landmark instantly associated with its city','an ordinary object nobody can identify','a private note with no shared meaning','广为人知的城市地标可称 iconic。'),Q('iconic',4,1,'The suffix -ic turns icon into an adjective meaning?','relating to or characteristic of an icon','without any picture or symbol','a person who builds a computer','-ic 构成与 icon 有关的形容词。')]);
P('iconographic','Iconographic 由 iconography 加 -ic 构成，形容研究或涉及艺术中约定俗成图像及其象征意义的。',C('iconographic.s1','艺术史','The iconographic analysis identified the lily in the painting as a symbol of purity rather than a decorative flower alone.','图像志分析把画中的百合认作纯洁的象征，而不只是装饰花朵。','The iconographic analysis identified the lily in the painting / as a symbol of purity / rather than a decorative flower alone.','iconographic 修饰 analysis，指解释图像符号含义的分析。','分析象征意义而非只描述画面，符合图像志研究。'),M('The curator called the inventory of frame sizes iconographic even though it interpreted no images or symbols.','The curator called the study of recurring religious symbols iconographic.','只记录画框尺寸、完全不解释图像，不属于图像志分析。'),[Q('iconographic',1,1,'Iconographic research focuses on?','the meanings of conventional images in art','the chemical makeup of paint only','the dates written on a frame','iconographic 关注艺术图像及其意义。'),Q('iconographic',2,1,'An iconographic reading of a painting might explain?','what a recurring symbol represents','how much the canvas weighs','the painter’s shoe size','图像志会解释反复出现的象征物。'),Q('iconographic',3,1,'Which study is iconographic?','interpreting the meaning of a halo in religious art','measuring a gallery’s wall length','counting visitors at the museum door','解释光环象征意义符合该词。'),Q('iconographic',4,1,'Iconographic is related to the noun?','iconography','icebox','hyperinflation','iconographic 与 iconography 同源。')]);
P('iconography','Iconography 源自希腊语 eikōn“图像”与 graphia“书写”，指某主题使用的图像符号集合或对其象征意义的研究。',C('iconography.s1','艺术符号','The exhibition’s iconography combined crowns, scales, and broken chains to represent authority, justice, and freedom.','展览的图像材料把王冠、天平和断裂的锁链结合起来，分别象征权威、正义与自由。','The exhibition’s iconography combined crowns, scales, and broken chains / to represent / authority, justice, and freedom.','iconography 可指一组图像符号；to represent 说明符号所表达的概念。','多个传统符号共同表现主题，体现图像材料义。'),M('The exhibition’s iconography contained no images, symbols, or interpretation of visual themes.','The exhibition’s iconography used recurring images and symbols to express its themes.','没有任何图像、符号或视觉主题，就没有此处所说的 iconography。'),[Q('iconography',1,1,'A film’s iconography may include?','recurring visual symbols and images','only the actors’ salaries','the chemical formula of its film stock','iconography 指作品中的图像符号。'),Q('iconography',2,1,'A scholar studying iconography asks?','what familiar images and symbols mean','how loud a theater’s speakers are','who bought the most tickets','图像学研究图像与符号的意义。'),Q('iconography',3,1,'Which item belongs to a ruler’s iconography?','a crown repeatedly shown as a symbol of authority','a private grocery receipt','an unmarked blank wall','王冠可成为统治者形象的象征元素。'),Q('iconography',4,1,'The Greek element graphia is associated with?','writing or representation','frozen water','temperature regulation','graphia 与书写、描绘有关。')]);
P('icy','Icy 由 ice 加 -y 构成，可指覆盖冰或像冰一样寒冷，也可比喻态度冷淡、不友善。',C('icy.s2','人际关系','Her icy reply ended the conversation; she answered without warmth and turned back to her work.','她冷淡的回答结束了谈话；她毫无热情地回应后又继续工作。','Her icy reply ended the conversation / she answered without warmth / and turned back to her work.','icy 修饰 reply，表示情感上冷淡；without warmth 解释语气。','缺少亲切回应体现比喻义。'),M('The host gave an icy welcome by smiling warmly, offering tea, and asking everyone to stay.','The host gave an icy welcome by refusing to greet the guests or speak to them.','热情微笑招待与冷淡态度相反。'),[Q('icy',1,1,'An icy road is?','covered with or made dangerously cold by ice','warm and dry in summer','soft like a wool blanket','icy 可指结冰的路面。'),Q('icy',2,2,'An icy reply sounds?','cold and unfriendly','warm and welcoming','loud but cheerful','比喻义指态度冷淡。'),Q('icy',3,1,'Which condition is icy?','a sidewalk coated with frozen water','a dry heated floor','a sunny beach with warm sand','结冰覆盖的地面是 icy。'),Q('icy',4,2,'An icy stare may make someone feel?','unwelcome or disliked','comforted by affection','hungry for dessert','冷淡目光会让人感到不受欢迎。')]);
P('id','Id 是弗洛伊德心理学术语，取自拉丁语 id“它”，指人格中寻求即时满足、较少顾及规则的无意识部分。',C('id.s1','心理学理论','In Freud’s model, the id seeks immediate pleasure, while other parts of the personality help balance those impulses with reality.','在弗洛伊德的模型中，本我寻求即时快感，而人格的其他部分帮助这些冲动与现实保持平衡。','In Freud’s model / the id seeks immediate pleasure / while other parts of the personality / help balance those impulses with reality.','id 是心理学名词；while 对比人格模型中不同部分的作用。','追求即时满足的冲动符合弗洛伊德理论中的本我。'),M('The textbook defined the id as the part of personality that always follows social rules and delays every pleasure.','The textbook defined the id as the part of personality that seeks immediate pleasure.','遵守规则并延迟满足与 id 的定义相反。'),[Q('id',1,1,'In Freudian theory, the id is the part of personality that?','seeks pleasure and immediate satisfaction','always plans according to social rules','stores a person’s official identification','id 指寻求快感和即时满足的部分。'),Q('id',2,1,'Which impulse best illustrates the id?','wanting the treat immediately without waiting','saving the treat for a planned celebration','checking a rule before choosing','不愿等待、立即享用体现本我冲动。'),Q('id',3,1,'The term id comes from a Latin word meaning?','it','ice','honor','拉丁语 id 意为“它”。'),Q('id',4,1,'The id is a concept in?','psychoanalytic theory','geometry','fungal biology','id 属于心理学理论术语。')]);
P('idea','Idea 源自希腊语 idea“形式、观念”，可指行动方案、抽象概念、意见、目的或对事物的大致印象。',[C('idea.s1','计划与创意','We had an idea for reducing food waste: the café could offer unsold meals to the shelter each evening.','我们想出一个减少食物浪费的办法：咖啡馆每天晚上把未售出的饭菜提供给收容所。','We had an idea for reducing food waste / the café could offer unsold meals / to the shelter each evening.','idea 表示行动建议；冒号后解释具体方案。','提出具体处理剩余餐食的办法，体现 s1。'),C('idea.s5','大致印象','I have no idea how long the repair will take, but the mechanic promised to call when he finds the fault.','我不清楚维修要花多久，但技工答应找到故障后打电话告知。','I have no idea how long the repair will take / but the mechanic promised to call / when he finds the fault.','have no idea 表示完全或大致不了解；how 引导间接疑问。','说话人对维修时长没有概念，体现印象义。')],M('The plan was a good idea because it increased waste and left the shelter without meals.','The plan was a good idea because it reduced waste and provided meals to the shelter.','增加浪费并不给收容所食物，不支持“好主意”的评价。'),[Q('idea',1,1,'An idea for what to do is a?','plan or suggestion','proof that an event happened','document proving someone’s identity','idea 可指行动建议。'),Q('idea',2,2,'The idea of gravity is a?','concept used to understand how objects attract','specific opinion about lunch','aim to travel tomorrow','idea 可指抽象概念。'),Q('idea',3,3,'“In my idea, the rule is unfair” expresses a?','view or opinion','physical plan for a room','rough impression of a smell','idea 也可表示看法。'),Q('idea',4,4,'If someone has no idea why the lights went out, they have no?','knowledge or understanding of the reason','intention to switch on a lamp','opinion about the room’s color','have no idea 表示不了解。')]);
P('ideal','Ideal 经晚期拉丁语 idealis、希腊语 idea“观念、形式”进入英语，可作形容词指最合适或想象中完美的，也可作名词指理想标准或完美典范。',C('ideal.s4','典范与榜样','For the new volunteers, Dr. Chen became an ideal of patient leadership because she listened carefully and shared credit.','陈医生以耐心倾听、乐于分享功劳，成了新志愿者心中理想的领导典范。','For the new volunteers / Dr. Chen became an ideal of patient leadership / because she listened carefully and shared credit.','ideal 作名词可指某类品质的完美代表；of 短语说明典范类型。','她体现了耐心领导的理想品质，符合 s4。'),M('The team called the unreliable model an ideal of accuracy even though it repeatedly produced incorrect results.','The team called the reliable model an ideal of accuracy because its results were consistently correct.','反复出错的模型不是准确性的典范。'),[Q('ideal',1,1,'An ideal location for a clinic is?','especially suitable for its purpose','impossible to reach and far from patients','a perfect world that exists only in imagination','ideal 形容词可指最合适的。'),Q('ideal',2,2,'An ideal world is often?','imagined as perfect, though perhaps unrealistic','a measured room in a real building','a type of computer symbol','ideal 也可指想象中完美的。'),Q('ideal',3,3,'A person’s ideal is a?','principle or standard worth pursuing','receipt proving a purchase','medical region under the brain','ideal 作名词可指理想目标。'),Q('ideal',4,4,'A model student may be an ideal of?','excellent study habits','careless attendance','a broken classroom desk','ideal 还可指完美典范。')]);
P('idealism','Idealism 由 ideal 加 -ism 构成，可指依循高尚理想生活的态度，也可指认为现实根本上属于精神或观念的哲学理论。',C('idealism.s2','哲学思想','The professor contrasted materialism with idealism, asking whether reality depends fundamentally on matter or on mind.','教授把唯物论与唯心论作对比，探问现实根本上依赖物质还是心灵。','The professor contrasted materialism with idealism / asking whether reality depends fundamentally / on matter or on mind.','idealism 在哲学语境中指唯心论；whether 引出待讨论的问题。','比较物质与精神作为现实根基，体现哲学义。'),M('The lecture defined philosophical idealism as the claim that reality is fundamentally material and independent of mind.','The lecture defined philosophical idealism as the view that reality is fundamentally mental or ideal.','现实根本上独立于心灵的观点不是唯心论定义。'),[Q('idealism',1,1,'As a personal attitude, idealism means?','living by high ideals, sometimes overlooking practical limits','refusing to value any principle','choosing only the cheapest object','idealism 可指坚持高尚理想。'),Q('idealism',2,2,'In philosophy, idealism is the theory that reality is fundamentally?','mental or ideal','made only of ice','a set of legal documents','哲学唯心论认为现实根本上是精神或观念的。'),Q('idealism',3,1,'A volunteer guided by idealism might?','work toward a noble goal despite practical difficulty','abandon every principle for convenience','avoid helping anyone','理想主义者会为高尚目标努力。'),Q('idealism',4,2,'Which debate concerns philosophical idealism?','whether mind is fundamental to reality','how to freeze a dessert','which icon opens a folder','唯心论讨论心灵与现实基础。')]);
P('idealistic','Idealistic 由 ideal 加 -istic 构成，形容受高尚目标驱动、重视原则而可能不够现实或不愿妥协的。',C('idealistic.s1','理想与实践','Her idealistic plan to give every child free instruments inspired donors, though the organizers still had to find storage space.','她提出让每个孩子免费获得乐器的理想计划，激励了捐赠者，不过组织者仍须解决存放空间。','Her idealistic plan to give every child free instruments / inspired donors / though the organizers still had to find storage space.','idealistic 修饰 plan，表示目标高尚；though 引出现实执行难题。','宏大的公益目标体现理想主义，同时面临实际限制。'),M('The proposal was idealistic because it rejected every generous goal and focused only on small personal profits.','The proposal was idealistic because it aimed to provide instruments to every child.','只关注个人小利与高尚目标相反。'),[Q('idealistic',1,1,'An idealistic proposal is guided by?','noble aims or high principles','a wish to avoid every moral goal','a list of verified measurements only','idealistic 指受高尚目标驱动。'),Q('idealistic',2,1,'Why can an idealistic plan seem impractical?','it may pursue an ambitious goal without enough attention to limits','it always has no goal at all','it is guaranteed to cost nothing','高尚目标可能忽视现实条件。'),Q('idealistic',3,1,'Which person sounds idealistic?','someone working toward equal education despite obstacles','someone rejecting every shared principle','someone choosing a task only for its price','为平等教育努力体现理想主义。'),Q('idealistic',4,1,'Idealistic is related to the noun?','idealism','iceberg','iconography','idealistic 与 idealism 同源。')]);
P('idealization','Idealization 由 idealize 加 -ation 构成，指把某人或过去描绘得近乎完美的过程，也可指由此形成的理想化形象。',C('idealization.s1','记忆与叙事','The memoir avoids idealization of the old neighborhood by describing both the close friendships and the unsafe streets.','这本回忆录没有把旧街区理想化，而是同时描写亲密友谊和不安全的街道。','The memoir avoids idealization of the old neighborhood / by describing both / the close friendships and the unsafe streets.','idealization 指把对象描绘得过于完美；avoids 表明作者有意避免这种做法。','同时呈现优点和缺点，避免把往事美化。'),M('The biography was an idealization because it included every flaw and made no person appear perfect.','The biography was an idealization because it removed flaws and presented the subject as perfect.','完整呈现缺点且不美化，不属于理想化描绘。'),[Q('idealization',1,1,'Idealization is the process of?','treating someone or something as more perfect than reality','listing faults without any interpretation','measuring an object with a ruler','idealization 指理想化。'),Q('idealization',2,1,'A memoir avoids idealization when it?','shows both the good and difficult parts of the past','removes every unpleasant memory','claims childhood was flawless','呈现复杂现实可避免过度美化。'),Q('idealization',3,1,'An idealization of a leader may?','present the leader as flawless','carefully include every limitation','record only neutral dates','理想化常把对象描绘得近乎完美。'),Q('idealization',4,1,'The noun idealization is related to the verb?','idealize','identify','ignite','idealization 来自 idealize。')]);
P('idealize','Idealize 由 ideal 加 -ize 构成，表示把人、过去或情境想象、描绘得比现实更完美。',C('idealize.s1','回忆与现实','As a teenager, Luis idealized life in the capital, but his first winter there showed him the cost and crowded streets as well.','十几岁时，路易斯把首都生活想得过于美好，但那里的第一个冬天也让他看到生活成本和拥挤街道。','As a teenager / Luis idealized life in the capital / but his first winter there showed him / the cost and crowded streets as well.','idealize 是及物动词，宾语是被美化的生活；but 引出真实情况。','他先把城市生活想象得完美，后来发现现实缺点。'),M('She idealized the trip by describing every delay and disappointment exactly as unpleasant.','She idealized the trip by remembering only the perfect moments and ignoring its problems.','如实描述不快经历并非把旅程美化。'),[Q('idealize',1,1,'To idealize a childhood is to?','remember or portray it as more perfect than it was','list every event without judgment','prove that childhood never happened','idealize 指把过去想得过于完美。'),Q('idealize',2,1,'A fan may idealize a public figure by?','ignoring the person’s flaws and imagining perfection','checking facts carefully before forming a view','describing both strengths and weaknesses','忽略缺点并想象完美属于 idealize。'),Q('idealize',3,1,'Which action idealizes a place?','showing only its beauty and hiding its problems','reporting its advantages and difficulties','measuring its streets accurately','只展现优点会美化地点。'),Q('idealize',4,1,'Idealize is built from ideal plus a suffix that forms?','a verb meaning to make or treat as ideal','a noun meaning a frozen drink','an adjective meaning unable to see','-ize 构成动词。')]);
P('identical','Identical 经晚期拉丁语 identicus、与 idem“同一”相关，形容两个或更多事物完全相同。',C('identical.s1','比较与识别','The twins wore identical blue jackets, so their teacher added name tags before the class trip.','这对双胞胎穿着完全相同的蓝色夹克，因此老师在班级出游前给夹克加上了姓名牌。','The twins wore identical blue jackets / so their teacher added name tags / before the class trip.','identical 修饰 jackets，表示外观完全相同。','老师需要姓名牌区分两件一样的夹克。'),M('The two forms were identical because one was blue, the other was red, and their numbers differed.','The two forms were identical because their color, text, and numbers all matched.','颜色和编号不同的表格不是完全相同。'),[Q('identical',1,1,'Two identical copies are?','exactly the same','similar in one small feature only','opposite in every detail','identical 表示完全相同。'),Q('identical',2,1,'Why label identical suitcases?','they look exactly alike and are easy to confuse','they are different sizes and colors','they contain no belongings','外观相同的行李难以区分。'),Q('identical',3,1,'Which pair is identical?','two forms with the same text, layout, and numbers','one red form and one blue form','two maps of different countries','内容和版式全部相同的一对才 identical。'),Q('identical',4,1,'Identical means more than merely?','similar','equal in every detail','exactly the same','identical 比仅仅相似程度更强。')]);
P('identical thing','Identical thing 是 identical“完全相同的”与 thing“事物”的组合，指与另一事物没有差别的同一件东西。',C('identical thing.s1','比较与指代','The two samples were not merely similar; under the test they were the identical thing taken from the same sealed container.','这两份样本不只是相似；检测表明它们是从同一个密封容器取出的同一件东西。','The two samples were not merely similar / under the test / they were the identical thing / taken from the same sealed container.','identical thing 是名词短语；not merely similar 强调两者完全相同。','同一容器中的样本被判断为同一件东西，而非仅仅相似。','源义仅解释完全相同的事物。'),M('The samples were the identical thing even though they came from different sources and had different contents.','The samples were similar but not the identical thing because their sources and contents differed.','来源和内容不同，不能说是同一件东西。'),[Q('identical thing',1,1,'An identical thing is?','the very same thing with no relevant difference','an unrelated object with a different purpose','something only vaguely similar','该短语指完全相同的东西。'),Q('identical thing',2,1,'If two samples are the identical thing, they are?','not merely alike but the same item','always made from different materials','impossible to compare','identical thing 强于“相似”，表示同一物。'),Q('identical thing',3,1,'Which pair could be called the identical thing?','two labels printed from the same file with matching details','two different books by different authors','a cup and a plate','相同文件印出的匹配标签可视为同一内容。'),Q('identical thing',4,1,'In the phrase identical thing, identical modifies?','thing','container','test','形容词 identical 修饰名词 thing。')]);
P('identifiable','Identifiable 由 identify 加 -able 构成，表示能够被辨认或确认身份、类别的。',C('identifiable.s1','观察与识别','The damaged label was still identifiable because the brand name and a corner of its logo remained visible.','受损的标签仍可辨认，因为品牌名称和一角标志还看得见。','The damaged label was still identifiable / because the brand name and a corner of its logo / remained visible.','identifiable 作表语，表示标签仍能被认出来；because 引出辨认依据。','残留的品牌名和标志让标签可以被识别。'),M('The specimen was identifiable because no feature or label could distinguish it from anything else.','The specimen was not identifiable because no feature or label distinguished it from others.','没有任何可辨认特征，说明无法识别。'),[Q('identifiable',1,1,'Something identifiable can be?','recognized as a particular person or thing','changed into a different language','used only once and then destroyed','identifiable 表示能够被辨认。'),Q('identifiable',2,1,'Why was the damaged label identifiable?','some distinctive name and logo remained visible','every printed mark had vanished','it was hidden inside an opaque box','残留标志提供识别线索。'),Q('identifiable',3,1,'Which item is identifiable?','a bird recognized by its unique colored band','an object with no visible or recorded features','a sound that nobody can hear','独特色带使鸟可以被辨认。'),Q('identifiable',4,1,'The suffix -able in identifiable indicates?','capability or possibility','a past action','a person who performs identification','-able 常表示能够……的。')]);
P('identification','Identification 来自 identify 加名词后缀 -ation，可指辨认身份的过程、证明身份的证件，或对他人感受的认同。',[C('identification.s1','调查与辨认','Witness identification was delayed until the investigator showed the witness a fair lineup rather than a single suspect.','调查人员先向证人展示公平的辨认队列，而非只展示一名嫌疑人，因此身份辨认被推迟。','Witness identification was delayed / until the investigator showed the witness / a fair lineup rather than a single suspect.','identification 指辨认过程；until 引出采取适当程序后的时间点。','通过队列辨认某人对应“识别身份”义。'),C('identification.s2','出行与证件','At the airport, staff asked each passenger to show identification before issuing a boarding pass.','机场工作人员在发放登机牌前要求每位旅客出示身份证明。','At the airport / staff asked each passenger to show identification / before issuing a boarding pass.','identification 作不可数名词，指证明身份的证件；before 引出先后步骤。','出示给工作人员核验的证件对应身份证明义。'),C('identification.s3','情感与文学','Readers may feel identification with the narrator when her account of grief resembles their own experience.','当叙述者对悲伤的描述与读者自身经历相似时，读者可能会对她产生认同感。','Readers may feel identification with the narrator / when her account of grief / resembles their own experience.','identification with 表示对某人感受的认同；when 引出产生共鸣的条件。','读者因相似经历理解叙述者，体现情感认同义。')],M('The guard accepted an empty envelope as identification because it proved the visitor’s name and photograph.','The guard accepted a passport as identification because it proved the visitor’s name and photograph.','空信封不能证明身份，护照才是身份证明。'),[Q('identification',1,1,'Witness identification is the process of?','recognizing who a person is','issuing a weather forecast','measuring a building’s height','s1 指辨认某人的身份。'),Q('identification',2,2,'At a security desk, identification usually means?','a document that proves who you are','a personal feeling of sympathy','a witness’s uncertain memory','s2 指身份证明文件。'),Q('identification',3,3,'A reader feels identification with a character when the reader?','recognizes shared feelings or experiences','checks the character’s passport','learns the character’s exact height','s3 指对他人感受产生认同。'),Q('identification',4,2,'Which item is most suitable as identification at an airport?','a passport','an unsigned blank sheet','a restaurant menu','护照可证明旅客身份。')]);
P('identify','Identify 来自拉丁语 identificare，含“使成为同一、确认身份”之意；现代英语可指认出、查明、感同身受或把两物视为相同。',[C('identify.s1','人物辨认','Mara could identify the caller by his familiar voice even though the connection was poor.','虽然通话线路很差，玛拉仍能凭熟悉的声音认出打电话的人。','Mara could identify the caller / by his familiar voice / even though the connection was poor.','identify someone 表示认出某人；by 引出辨认依据。','熟悉的声音帮助她认出打电话者。'),C('identify.s2','研究与诊断','The lab used a genetic test to identify the bacteria causing the persistent infection.','实验室用基因检测查明了导致持续感染的细菌。','The lab used a genetic test / to identify the bacteria / causing the persistent infection.','identify 在此表示查明确切性质；to 引出检测目的。','检测确定了感染的具体病原体。'),C('identify.s3','共情与理解','I identify with the new student because I also remember how difficult it was to start at an unfamiliar school.','我能理解新同学的感受，因为我也记得刚到陌生学校时有多难。','I identify with the new student / because I also remember / how difficult it was to start at an unfamiliar school.','identify with 表示认同并理解某人的感受；because 说明共鸣来源。','说话者有相似经历，因此能理解新生。'),C('identify.s4','逻辑与分类','The report incorrectly identifies correlation with causation, although the two concepts are not the same.','报告错误地把相关性等同于因果关系，尽管这两个概念并不相同。','The report incorrectly identifies correlation with causation / although the two concepts / are not the same.','identify A with B 可表示把 A 与 B 等同；although 引出纠正。','报告把两个不同概念当成一个。')],M('The technician identified the component when she guessed randomly without checking its label or function.','The technician identified the component after checking its label and function.','不经检查而随意猜测不构成可靠的辨认或确认。'),[Q('identify',1,1,'To identify a caller is to?','recognize who is calling','send the caller a package','make the call end sooner','s1 表示认出某人。'),Q('identify',2,2,'A lab identifies a pathogen when it?','determines exactly which organism caused the illness','decides whether the patient likes the lab','changes the organism into a medicine','s2 表示查明具体病原体。'),Q('identify',3,3,'To identify with another person is to?','feel that you understand and share their experience','prove their legal name with a card','treat two objects as physically identical','s3 表示产生情感共鸣。'),Q('identify',4,4,'The report identifies A with B when it?','treats the two as the same','recognizes a caller’s voice','finds a bacterium in a sample','s4 表示把两者等同看待。')]);
P('identity','Identity 经拉丁语 identitas、源自 idem“同一”，可指一个人是谁、个人或群体的独特特性、归属认同，也可指数学恒等式。',[C('identity.s1','个人信息','The clinic checked each patient’s identity before releasing medical records to prevent a mix-up.','诊所先核实每位患者的身份，再提供病历，以免弄错对象。','The clinic checked each patient’s identity / before releasing medical records / to prevent a mix-up.','identity 指“某人是谁”；before 表示先核实身份再提供资料。','核实患者身份可避免把病历交错人。'),C('identity.s2','文化与群体','The language, food, and stories of the island form an important part of its cultural identity.','这座岛屿的语言、饮食和故事构成其文化特性的重要部分。','The language, food, and stories of the island / form an important part / of its cultural identity.','identity 指使群体具有区别性的特征；of 短语说明其所属群体。','语言、饮食和故事塑造群体的独特文化。'),C('identity.s3','社会归属','Joining the local choir gave Nia a stronger sense of identity and belonging in her new town.','加入当地合唱团让妮娅在新城镇中更有归属感和认同感。','Joining the local choir / gave Nia a stronger sense of identity and belonging / in her new town.','sense of identity 指归属认同感；joining 表示带来这种感受的经历。','参加群体活动带来归属感。'),C('identity.s4','代数','Because x + 0 = x for every value of x, the teacher called the equation an identity.','由于对任意 x 都有 x + 0 = x，老师把这个等式称为恒等式。','Because x + 0 = x for every value of x / the teacher called the equation / an identity.','identity 在数学中指对所有变量值都成立的等式；because 说明条件。','等式对所有 x 成立，符合恒等式定义。')],M('The equation x + 0 = x was not an identity because it failed for every value of x.','The equation x + 0 = x was an identity because it held for every value of x.','该等式对所有 x 都成立，正是恒等式。'),[Q('identity',1,1,'A person’s identity answers the question?','who that person is','how much an object weighs','where a sentence ends','s1 指某人是谁。'),Q('identity',2,2,'A group’s cultural identity may include its?','distinctive language, traditions, and stories','members’ shoe sizes only','unrelated weather records','s2 指群体独特的文化特征。'),Q('identity',3,3,'A sense of identity and belonging is a feeling of?','being connected to a group','having a passport photograph','solving an equation','s3 表示归属感。'),Q('identity',4,4,'In mathematics, an identity is an equation that?','is true for all allowed values of its variables','is true for just one guessed value','contains no variables or numbers','s4 指对变量所有允许取值都成立的等式。')]);
P('ideological','Ideological 由 ideology 加 -ical 构成，形容与影响政治或政策的一套观念体系有关。',C('ideological.s1','政策与观念','The debate was ideological as well as economic: the two parties disagreed about the role the state should play in public services.','这场辩论既涉及经济，也涉及意识形态：两党对政府应在公共服务中发挥什么作用意见不同。','The debate was ideological as well as economic / the two parties disagreed / about the role the state should play in public services.','ideological 修饰 debate，表示辩论涉及政治观念体系；as well as 表示兼有两方面。','双方对政府角色的理念分歧具有意识形态性质。'),M('The dispute was ideological because both groups agreed completely on the political principles behind the policy.','The dispute was ideological because the groups had conflicting political principles behind the policy.','双方理念一致，不构成意识形态分歧。'),[Q('ideological',1,1,'An ideological disagreement concerns?','a system of political or moral ideas','the spelling of a person’s name','only the temperature of a room','ideological 与观念体系有关。'),Q('ideological',2,1,'Why might a debate about the state’s role be ideological?','it reflects competing beliefs about politics and society','it concerns only the color of a printed ballot','it has no connection to ideas','政府角色涉及政治观念。'),Q('ideological',3,1,'Which is an ideological question?','what principles should guide public policy','how many chairs fit in a room','which file was saved last','公共政策应依据何种原则属于观念问题。'),Q('ideological',4,1,'Ideological is formed from the noun?','ideology','identity','idiom','ideological 源于 ideology。')]);
P('ideologically','Ideologically 是 ideological 加副词后缀 -ly，表示依据某种政治、道德或社会观念体系。',C('ideologically.s1','政治分析','The candidates were ideologically close on education policy, though they proposed different ways to fund the same programs.','两位候选人在教育政策上的意识形态立场接近，尽管他们提出了不同的项目筹资办法。','The candidates were ideologically close / on education policy / though they proposed different ways to fund the same programs.','ideologically 修饰 close，说明双方按思想立场来看接近；though 引出政策手段的差别。','观念立场相近，但具体筹资办法仍不同。'),M('The candidates were ideologically alike because their political principles were entirely opposite.','The candidates were ideologically different because their political principles were opposite.','政治原则完全相反，不能说观念立场相似。'),[Q('ideologically',1,1,'Ideologically means?','according to a system of political or moral ideas','according to a person’s height','in alphabetical order','该副词表示从观念体系角度看。'),Q('ideologically',2,1,'Two parties ideologically close on a policy?','share similar underlying beliefs about it','must use identical funding methods','cannot disagree about any practical detail','观念接近并不意味着实践方案完全相同。'),Q('ideologically',3,1,'An ideologically motivated choice is guided by?','political or moral principles','random weather changes','the shape of a letter','意识形态动机来自政治或道德原则。'),Q('ideologically',4,1,'Ideologically is the adverb form of?','ideological','ideology','identifiable','ideologically 由形容词 ideological 加 -ly 构成。')]);
P('ideology','Ideology 经法语 idéologie、由希腊语 idea“观念”与 -logia“研究、论说”构成，可指群体的信念体系或某时期、团体特有的一套观念。',[C('ideology.s1','政治与社会','The movement’s ideology emphasized equal access to education and public health, and its members organized campaigns around those beliefs.','该运动的思想体系强调平等获得教育和公共卫生服务，成员围绕这些信念组织宣传活动。','The movement’s ideology emphasized equal access / to education and public health / and its members organized campaigns around those beliefs.','ideology 指群体持有的信念体系；and 连接思想内容与行动。','多个信念共同指导运动成员的行动，体现思想体系义。'),C('ideology.s2','历史观念','The historian studied the ideology of the early industrial period by examining its assumptions about work, progress, and social class.','历史学家研究早期工业时期的观念方式，考察当时对劳动、进步和阶级的看法。','The historian studied the ideology of the early industrial period / by examining its assumptions / about work, progress, and social class.','ideology 可指某一时期特有的一套观念；by 引出研究方法。','这些关于社会的典型观念属于特定历史时期。')],M('The group’s ideology was its system of shared beliefs, even though its members held no common ideas or principles.','The group’s ideology was its system of shared beliefs and principles.','没有共同观念或原则，就没有所说的信念体系。'),[Q('ideology',1,1,'A political ideology is?','a system of ideas and beliefs held by a group','a document that proves one person’s name','a phrase with a figurative meaning','s1 指群体持有的观念信念体系。'),Q('ideology',2,2,'A historian may study a period’s ideology by examining its?','characteristic beliefs about work and society','weather on one isolated afternoon','the number of pages in a diary','s2 指某时期特有的观念。'),Q('ideology',3,1,'A movement’s ideology can influence?','the campaigns and policies its members support','only the color of their notebooks','the spelling of every family name','共同信念可指导运动的行动。'),Q('ideology',4,2,'Which topic best illustrates an ideology of an era?','widely held assumptions about progress and social class','one worker’s lunch receipt','a list of unrelated street addresses','某时期普遍的社会观念体现其意识形态。')]);
P('ideomotor','Ideomotor 由希腊语 idea“观念”与 motor“运动”构成，描述仅因想到某个动作而引起的细微、不自觉运动。',C('ideomotor.s1','心理与运动','In an ideomotor response, tiny unintentional movements can guide a pointer toward an answer a person is consciously trying not to choose.','在观念运动反应中，细微的无意识动作可能推动指针指向一个人有意识地试图不去选择的答案。','In an ideomotor response / tiny unintentional movements can guide a pointer / toward an answer a person is consciously trying not to choose.','ideomotor 修饰 response，指由念头引发细微动作的反应；trying not to choose 对比无意识影响。','指针受无意的细微动作推动，说明观念可能引起运动。'),M('The response was ideomotor because the pointer moved only when a motor mechanically turned it, with no human movement involved.','The response was ideomotor because a person’s thought could prompt subtle involuntary movement.','完全由机械驱动、没有人的动作，不符合观念运动反应。'),[Q('ideomotor',1,1,'An ideomotor movement is caused by?','a thought or idea prompting a small movement','a heavy object falling from a height','a deliberate speech sound','词中的 idea 与 motor 表示观念引发运动。'),Q('ideomotor',2,1,'An ideomotor response may involve?','subtle movements a person does not intend','a large planned athletic jump','a change in eye color','其特征是细微且非故意的动作。'),Q('ideomotor',3,1,'Why can a pointer move in an ideomotor task?','unnoticed muscle movements may guide it','the pointer reads a person’s mind directly','the table always tilts by itself','无意识肌肉动作可能推动指针。'),Q('ideomotor',4,1,'Ideomotor combines a reference to ideas with?','movement','identity documents','figurative phrases','motor 指运动。')]);
P('idiocy','Idiocy 由 idiot 加 -cy 构成，指极其缺乏判断力的行为或愚蠢之举；用来骂人时带有冒犯性。',C('idiocy.s1','批评与判断','The editor called the decision to delete the only backup an act of idiocy, not a harmless technical mistake.','编辑把删除唯一备份的决定称为愚蠢之举，而不是无害的技术失误。','The editor called the decision to delete the only backup / an act of idiocy / not a harmless technical mistake.','idiocy 指愚蠢的行为；an act of 将评价落在决定上。','删除唯一备份显示严重缺乏判断。','该词语气强烈，批评行为时仍可能显得刺耳。'),M('Deleting the only backup was idiocy because it was a careful decision that preserved every copy.','Deleting the only backup was an act of idiocy because it destroyed the last recoverable copy.','谨慎保留所有副本不属于愚蠢行为。'),[Q('idiocy',1,1,'Idiocy means?','behavior showing a complete lack of sense','a formal method of identification','a type of mathematical equation','idiocy 指愚蠢或缺乏判断的行为。'),Q('idiocy',2,1,'Why was deleting the only backup called idiocy?','it foolishly destroyed the last recoverable copy','it safely created several new copies','it was required by a careful storage plan','删除唯一备份是严重失策。'),Q('idiocy',3,1,'Idiocy is a word with a?','strongly critical and potentially offensive tone','neutral meaning of official paperwork','technical meaning of a conic curve','该词批评性强，使用时要注意语气。'),Q('idiocy',4,1,'The noun idiocy is related to?','idiot','ideology','icecap','idiocy 由 idiot 加后缀构成。')]);
P('idiom','Idiom 经法语和拉丁语源自希腊语 idioma“个人特有的表达”，可指不能按字面拆解的习语、某群体的语言风格，或艺术与音乐的特色表达方式。',[C('idiom.s1','语言学习','“Spill the beans” is an idiom meaning “reveal a secret,” so its meaning cannot be worked out by translating each word literally.','“Spill the beans”是一条意为“泄露秘密”的习语，不能靠逐字翻译推断其含义。','“Spill the beans” is an idiom / meaning “reveal a secret” / so its meaning cannot be worked out by translating each word literally.','idiom 指整体含义无法由单个词直接推知的固定表达；so 引出不能逐字理解的结果。','短语的实际意思不是把 beans 逐字理解。'),C('idiom.s2','语言风格','The poet’s idiom blends regional vocabulary with short, direct sentences that sound natural in her community.','这位诗人的语言风格把地方词汇与简短直接的句子结合起来，听来自然亲切。','The poet’s idiom blends regional vocabulary / with short, direct sentences / that sound natural in her community.','idiom 指某人或群体自然的表达风格；that 从句修饰句子。','地方词汇与句式体现诗人的语言特色。'),C('idiom.s3','音乐与艺术','The composer kept the folk idiom of the original tune while arranging it for a modern string quartet.','作曲家为现代弦乐四重奏改编曲子时，保留了原曲的民间音乐风格。','The composer kept the folk idiom of the original tune / while arranging it / for a modern string quartet.','idiom 指艺术或音乐的特色风格；while 引出改编时仍保留的特点。','保留民间曲调的特色方式，体现音乐风格义。')],M('“Spill the beans” is an idiom meaning to cook legumes because its figurative meaning must be guessed from no context.','“Spill the beans” is an idiom meaning to reveal a secret, not to cook legumes.','该固定表达按习惯含义指泄密，而非字面烹饪。'),[Q('idiom',1,1,'An idiom is a phrase whose meaning?','cannot be understood simply from its separate words','must always be a mathematical identity','is the same in every language by rule','s1 指整体含义不能由字面词义推断的短语。'),Q('idiom',2,2,'A writer’s idiom refers to the writer’s?','characteristic, natural style of expression','official proof of identity','ability to recognize a face','s2 指个人或群体的语言特色。'),Q('idiom',3,3,'A folk idiom in music is its?','distinctive artistic or musical style','list of performers’ passport numbers','literal dictionary translation','s3 指艺术或音乐中的特色风格。'),Q('idiom',4,1,'“Spill the beans” is an idiom when it means?','reveal a secret','pour seeds onto a table','identify a caller','其习惯意义是泄露秘密。')]);
P('idiomatic','Idiomatic 由 idiom 加形容词后缀 -atic 构成，表示符合某种语言习惯、包含该语言自然使用的固定表达。',C('idiomatic.s1','翻译与表达','The sentence was grammatically correct but not idiomatic, so a native speaker replaced the literal phrase with a more natural one.','这个句子语法正确但不符合英语习惯，因此母语者把直译短语换成更自然的说法。','The sentence was grammatically correct but not idiomatic / so a native speaker replaced the literal phrase / with a more natural one.','idiomatic 表示自然符合语言习惯；but 对照语法正确与表达自然。','直译虽合语法，却不自然，说明不够 idiomatic。'),M('The translation sounded idiomatic because it copied every source-language phrase word for word and sounded unnatural.','The translation sounded idiomatic because it used expressions natural to English.','逐词照搬且不自然的译文不符合英语习惯。'),[Q('idiomatic',1,1,'An idiomatic expression is?','natural to a particular language','always a literal translation','an official document proving identity','idiomatic 指符合某语言自然用法。'),Q('idiomatic',2,1,'A sentence can be grammatical but not idiomatic if it?','follows rules but sounds unnatural to fluent speakers','contains no grammatical structure','uses every common phrase correctly','合乎语法不代表表达自然。'),Q('idiomatic',3,1,'How can a translator make wording idiomatic?','choose expressions natural to the target language','preserve every source word in the same order','remove all verbs','译文需采用目标语言自然表达。'),Q('idiomatic',4,1,'Idiomatic is related to the noun?','idiom','idler','idol','idiomatic 由 idiom 派生。')]);
P('idiosyncrasy','Idiosyncrasy 源自希腊语 idios“自己的”与 synkrasis“混合、性情”，指个人或群体特有的、不同寻常的习惯或特点。',C('idiosyncrasy.s1','个性与习惯','One of Malik’s idiosyncrasies is labeling every notebook by the month in which he began it.','马利克的一个独特习惯是按开始使用的月份给每本笔记本贴标签。','One of Malik’s idiosyncrasies / is labeling every notebook / by the month in which he began it.','idiosyncrasy 指个人独特的习惯或特点；one of 后接复数名词。','按月份给笔记本贴标签是他与众不同的个人习惯。'),M('Labeling each notebook by its starting month was an idiosyncrasy shared by everyone in the city and considered entirely universal.','Labeling each notebook by its starting month was Malik’s personal idiosyncrasy.','普遍共享的习惯不宜称作某个人特有的特点。'),[Q('idiosyncrasy',1,1,'An idiosyncrasy is?','an unusual habit or distinctive personal feature','a phrase understood only literally','a document showing a person’s name','该词指独特习惯或特点。'),Q('idiosyncrasy',2,1,'Which is a personal idiosyncrasy?','always labeling notebooks by the month they were started','using the same standard form as everyone else','following a posted safety rule','独特的记事方式可成为个人习惯。'),Q('idiosyncrasy',3,1,'An idiosyncrasy usually belongs to?','a particular person or group','every person in exactly the same way','a mathematical curve only','它是个人或群体独有的特征。'),Q('idiosyncrasy',4,1,'Which adjective shares the root of idiosyncrasy?','idiosyncratic','ideological','identical','idiosyncratic 意为具有个人独特性的。')]);
P('idiosyncratic','Idiosyncratic 由 idiosyncrasy 加形容词后缀 -ic 构成，形容某人或某物具有独特、非典型的个人特点。',C('idiosyncratic.s1','个人风格','Her idiosyncratic filing system used colored ribbons instead of folders, but she could retrieve any letter in seconds.','她独特的归档方法用彩色丝带而不用文件夹，不过她几秒钟就能找到任一封信。','Her idiosyncratic filing system / used colored ribbons instead of folders / but she could retrieve any letter in seconds.','idiosyncratic 修饰 filing system，表示具有个人特质而非通用；but 引出其仍然有效。','彩带归档方法独特，符合 idiosyncratic。'),M('His idiosyncratic method was the same standard procedure followed identically by every office.','His idiosyncratic method had a distinctive personal feature that differed from the usual procedure.','完全标准化且人人相同的方法谈不上个人独特性。'),[Q('idiosyncratic',1,1,'An idiosyncratic style is?','distinctive and characteristic of one person','identical to every standard style','impossible to recognize','该词表示独特且有个人特征。'),Q('idiosyncratic',2,1,'Why was the filing system idiosyncratic?','it used the owner’s unusual ribbon method','it copied the same folder system as every office','it had no system at all','彩带方法不同于常规归档。'),Q('idiosyncratic',3,1,'An idiosyncratic choice is most likely?','unusual in a way associated with a particular person','required by a universal rule','chosen at random by every user','它与某个人的独特方式相关。'),Q('idiosyncratic',4,1,'Idiosyncratic is closely related to?','idiosyncrasy','idiom','identification','idiosyncratic 与 idiosyncrasy 同根。')]);
P('idiot','Idiot 经拉丁语 idiota 源自希腊语 idiōtēs，现代口语中是对愚蠢之人的侮辱性称呼；早期医学义已经过时且有污名。',C('idiot.s1','对话与语气','After the near collision, Bea muttered that calling the distracted driver an idiot would not make the road safer.','险些相撞后，比娅低声说，骂走神的司机是“傻瓜”并不会让道路更安全。','After the near collision / Bea muttered that calling the distracted driver an idiot / would not make the road safer.','idiot 在此是带侮辱性的名词；that 引出比娅所说的内容。','语境明确显示它是骂人的称呼，并非中性诊断。'),M('He called the careful driver an idiot as a respectful medical diagnosis of intelligence.','He used idiot as an insult, although a calmer description would criticize the unsafe driving.','idiot 是侮辱性口语称呼，不是尊重的医学诊断。','register'),[Q('idiot',1,1,'In modern informal use, an idiot is?','an insulting word for a very foolish person','a neutral identity document','a person’s distinctive language style','该词口语中是侮辱性称呼。'),Q('idiot',2,1,'Why should a speaker use idiot carefully?','it can insult or demean someone','it is the only polite word for a mistake','it is a technical term for a curve','idiot 具有冒犯性。'),Q('idiot',3,1,'Which sentence uses idiot as an insult?','“You idiot,” he shouted after the reckless choice.','“Please show your identification,” said the guard.','“That phrase is an idiom,” said the tutor.','第一句用该词责骂对方。'),Q('idiot',4,1,'The historical medical use of idiot is?','outdated and stigmatizing','the preferred modern clinical diagnosis','a synonym for identity','旧医学用法过时且带污名。')]);
P('idiotic','Idiotic 由 idiot 加形容词后缀 -ic 构成，形容行为或主意愚蠢得不合常理；用来评价人时可能显得冒犯。',C('idiotic.s1','决策与后果','It was idiotic to leave the laboratory door unlocked overnight after the expensive equipment had been delivered.','昂贵设备送到后，实验室的门整夜不锁，这个做法愚蠢得不合常理。','It was idiotic / to leave the laboratory door unlocked overnight / after the expensive equipment had been delivered.','idiotic 评价做法缺乏判断；to 不定式说明被评价的行为。','贵重设备无人看管而不锁门，显示判断失当。'),M('Leaving the laboratory secured all night was idiotic because it protected the equipment from theft.','Leaving the laboratory unlocked with valuable equipment inside was idiotic because it invited theft.','锁好实验室是保护设备的合理做法。'),[Q('idiotic',1,1,'An idiotic decision is?','extremely foolish or lacking good judgment','carefully considered and sensible','a proof of someone’s legal identity','idiotic 表示极其愚蠢。'),Q('idiotic',2,1,'Why was leaving the lab unlocked idiotic?','valuable equipment was exposed to theft','the equipment was already safely stored elsewhere','the lab had no door','行为忽略了明显风险。'),Q('idiotic',3,1,'Which adjective is closest in meaning to idiotic?','foolish','careful','identical','idiotic 与 foolish 意义相近。'),Q('idiotic',4,1,'Idiotic is formed from which noun?','idiot','idiom','ideology','idiotic 由 idiot 派生。')]);
P('idle','Idle 来自古英语 īdel“空虚、无用”，可形容闲置或懒惰、无根据的事物，也可作动词表示闲混或让发动机空转。',[C('idle.s1','设备与使用','The backup generator remained idle for most of the year, but technicians tested it monthly so it would work in an outage.','备用发电机一年中大部分时间都闲置着，不过技术人员每月测试一次，确保停电时能用。','The backup generator remained idle for most of the year / but technicians tested it monthly / so it would work in an outage.','idle 描写设备未使用；but 表示虽闲置仍定期测试。','发电机平时没有工作，体现闲置义。'),C('idle.s2','工作习惯','Rather than let the staff sit idle, the supervisor assigned them a useful training task during the quiet shift.','主管没有让员工无所事事，而是在安静的班次安排了一项有用的培训任务。','Rather than let the staff sit idle / the supervisor assigned them / a useful training task during the quiet shift.','sit idle 指无所事事；rather than 引出主管选择的替代做法。','员工原本会闲坐无事。'),C('idle.s3','传闻与证据','The newspaper dismissed the rumor as idle speculation because no witness or document supported it.','报纸把这条传闻斥为毫无根据的猜测，因为没有证人或文件支持它。','The newspaper dismissed the rumor as idle speculation / because no witness or document / supported it.','idle 修饰 speculation，表示没有根据或实际依据；because 解释判断理由。','缺少证据使传闻成为无根据的猜测。'),C('idle.s4','时间安排','We idled away the afternoon on the porch, chatting while the rain passed.','我们在门廊上闲聊着消磨了整个下午，等雨停。','We idled away the afternoon / on the porch / chatting while the rain passed.','idle away time 指闲混、消磨时间；while 引出同时发生的聊天。','闲聊度过下午体现动词的消磨时光义。'),C('idle.s5','机械运行','The mechanic let the engine idle for a minute before checking whether the warning light returned.','技师让发动机空转一分钟，再检查警示灯是否重新亮起。','The mechanic let the engine idle for a minute / before checking / whether the warning light returned.','engine idle 指发动机低速运转而车辆不行驶；before 标出先后顺序。','发动机在车辆未行驶时低速运转。')],M('The engine idled while the car sped down the highway at full speed.','The engine idled while the car remained stationary and ran at low speed.','发动机空转指低速运转而车辆不行驶。'),[Q('idle',1,1,'An idle machine is?','not being used or operating','being used continuously at full output','already dismantled into parts','s1 指设备未使用。'),Q('idle',2,2,'A worker sitting idle is?','doing no work at that time','working at maximum speed','repairing an engine','s2 指无所事事。'),Q('idle',3,3,'Idle speculation is?','guesswork without a sound basis','a conclusion proved by documents','a type of identity card','s3 指无根据的猜测。'),Q('idle',4,5,'When an engine idles, it?','runs slowly while the vehicle is not moving','is switched off and cannot run','moves the vehicle at highway speed','s5 指发动机空转。')]);
P('idler','Idler 由 idle 加表示人的后缀 -er 构成，指逃避工作、习惯于无所事事的人。',C('idler.s1','工作与责任','The foreman warned that an idler who repeatedly avoided assigned duties would not remain on the crew.','工头警告说，反复逃避分派任务的懒汉不会继续留在队里。','The foreman warned / that an idler who repeatedly avoided assigned duties / would not remain on the crew.','idler 指逃避工作的人；who 从句说明此人的行为。','反复躲避工作说明此人习惯懒散。'),M('The supervisor called the most diligent worker an idler because she completed every assigned task on time.','The supervisor called the worker who avoided assigned duties an idler.','按时完成所有任务与逃避工作相反。'),[Q('idler',1,1,'An idler is someone who?','avoids work','identifies unknown objects','writes figurative phrases','idler 指懒于工作的人。'),Q('idler',2,1,'Which person is an idler?','someone who repeatedly avoids assigned duties','someone who finishes every task carefully','someone who gives a witness identification','逃避任务符合 idler 的含义。'),Q('idler',3,1,'The suffix -er in idler refers to?','a person associated with an action or quality','a document proving a person’s identity','an equation true for all values','-er 在此构成人的名词。'),Q('idler',4,1,'Idler is derived from which adjective?','idle','ideal','idiomatic','idler 来自 idle。')]);
P('idol','Idol 经古法语和拉丁语源自希腊语 eidōlon“形象、影像”，可指受崇拜的人或事物，也可指被供奉的神像。',[C('idol.s1','公众人物','To the young violinists, the retired soloist was an idol whose recordings had inspired them to practice.','对年轻小提琴手来说，那位退休独奏家是他们崇拜的偶像；他的录音曾激励他们练习。','To the young violinists / the retired soloist was an idol / whose recordings had inspired them to practice.','idol 指受到极大钦佩的人；whose 引出偶像产生影响的方式。','年轻音乐家钦佩这位演奏家，体现崇拜对象义。'),C('idol.s2','宗教图像','The museum displayed a small wooden idol from the ancient shrine, with a note explaining its ritual use.','博物馆展出一尊来自古代神龛的小木神像，并附有说明其仪式用途的标签。','The museum displayed a small wooden idol / from the ancient shrine / with a note explaining its ritual use.','idol 指被当作神明供奉的图像或雕像；from 短语标明其来源。','木制神像曾用于宗教仪式。'),C('idol.s3','珍爱之物','For the collector, the battered first edition was an idol, treasured above every newer copy.','对这位收藏家来说，那本磨损的初版是珍爱之物，比任何较新的版本都宝贵。','For the collector / the battered first edition was an idol / treasured above every newer copy.','idol 可比喻极受珍爱的事物；treasured 补充说明其价值。','收藏家把初版看得极为珍贵。')],M('The carved wooden idol was merely an ordinary office chair and had never been treated as sacred.','The carved wooden idol was an image worshipped as a deity at the shrine.','作为普通椅子且从未被奉为神明的物件，不是宗教神像。'),[Q('idol',1,1,'A famous singer can be someone’s idol because the singer is?','greatly admired','unable to be recognized','a phrase with a hidden meaning','s1 指受钦佩的人。'),Q('idol',2,2,'A carved idol in a shrine is?','an image or statue worshipped as a god','a proof of identity','a machine running without movement','s2 指宗教供奉的神像。'),Q('idol',3,3,'A collector might call a treasured first edition an idol to mean?','something greatly loved or valued','a book that cannot be read','a completely idle object','s3 可指极珍爱的事物。'),Q('idol',4,1,'Which sentence uses idol for an admired person?','The young players treated the veteran as their idol.','The guard checked her identification.','The engine idled in the garage.','第一句将资深选手称为偶像。')]);
P('idolize','Idolize 由 idol 加动词后缀 -ize 构成，表示极度崇拜、爱慕某人或把某人理想化。',C('idolize.s1','名人与崇拜','The coach told the young players not to idolize one star so completely that they ignored the work of the rest of the team.','教练提醒年轻队员不要过分崇拜某位明星，以至于忽视了队里其他人的努力。','The coach told the young players / not to idolize one star so completely / that they ignored the work of the rest of the team.','idolize 是及物动词，宾语是受崇拜的人；so…that 描述过度崇拜的结果。','把明星看得过于重要而忽略团队，体现 idolize。'),M('The fans idolized the player by refusing to admire or follow anything he did.','The fans idolized the player by admiring him intensely and treating him as a hero.','拒绝钦佩与 idolize 的崇拜义相反。'),[Q('idolize',1,1,'To idolize a performer is to?','admire or love the performer intensely','avoid noticing the performer','prove the performer’s identity','idolize 表示极度崇拜。'),Q('idolize',2,1,'A coach warns players not to idolize one star when they?','treat that star as so important that they overlook others','respect every teammate equally','practice the sport regularly','过度崇拜某人会忽视他人。'),Q('idolize',3,1,'Which action shows idolizing?','treating a public figure as nearly perfect and following everything they do','checking a public figure’s name on a form','criticizing a single decision fairly','把公众人物视为近乎完美体现崇拜。'),Q('idolize',4,1,'Idolize is formed from idol plus a suffix that makes?','a verb meaning to treat with great admiration','a noun meaning a language phrase','an adjective meaning not in use','-ize 构成动词。')]);
P('idyllic','Idyllic 由 idyll 加形容词后缀 -ic 构成，形容宁静、愉快得仿佛完美的地方或情景。',C('idyllic.s1','旅行与风景','The family found an idyllic cove where clear water, quiet paths, and a small village made the afternoon seem almost perfect.','一家人在海湾发现一处恬静宜人的地方：清澈海水、安静小径和小村庄让午后近乎完美。','The family found an idyllic cove / where clear water, quiet paths, and a small village / made the afternoon seem almost perfect.','idyllic 修饰 cove，表示环境宁静愉悦；where 从句描写其特点。','安静而美好的环境营造出近乎完美的景象。'),M('The supposedly idyllic cove was noisy, polluted, and crowded, with no calm or pleasant setting.','The idyllic cove was calm and pleasant, with clear water and quiet paths.','嘈杂、污染和拥挤与恬静美好相反。'),[Q('idyllic',1,1,'An idyllic setting is?','calm and pleasant, almost perfect','dangerous and extremely noisy','a system of political beliefs','idyllic 指恬静美好的。'),Q('idyllic',2,1,'Which place seems idyllic?','a quiet cove with clear water and peaceful paths','a polluted harbor beside a loud factory','a crowded station during an emergency','宁静海湾更符合 idyllic。'),Q('idyllic',3,1,'Idyllic is often used to describe?','a place or scene','an identity document','a grammatical conjunction','该词常描述地方或景色。'),Q('idyllic',4,1,'An idyllic afternoon would most likely feel?','peaceful and delightful','hostile and chaotic','uninformed and rude','其含义带有宁静愉悦之意。')]);
P('if','If 源自古英语 gif，可作连词表示条件“如果”、引导间接疑问“是否”或表示让步“即使”，也可作名词指不确定的条件。',[C('if.s1','条件与计划','If the clouds clear before noon, the guide will lead the group to the ridge.','如果云层在中午前散开，向导就会带大家前往山脊。','If the clouds clear before noon / the guide will lead the group / to the ridge.','if 引出真实条件从句；主句说明条件实现后的计划。','带队计划取决于云层是否散开。'),C('if.s2','间接疑问','Mina asked if the museum was open on Mondays before she planned the visit.','米娜在安排参观前询问博物馆星期一是否开放。','Mina asked if the museum was open on Mondays / before she planned the visit.','if 引导间接疑问从句，意为“是否”；before 表示先询问再计划。','问题询问开放与否，体现间接疑问用法。'),C('if.s3','让步','Even if the first experiment fails, the team will record the results and adjust the design.','即使第一次实验失败，团队也会记录结果并调整设计。','Even if the first experiment fails / the team will record the results / and adjust the design.','even if 表示“即使”，引出不影响主句的让步条件。','实验失败也不会改变团队记录和改进的安排。'),C('if.s4','可能性与条件','There is always an if in the proposal: what if the only supplier closes before delivery?','这个提案总有一个未定因素：如果唯一的供货商在交货前关门怎么办？','There is always an if in the proposal / what if the only supplier closes / before delivery?','if 作名词指一个不确定条件；what if 引出可能发生的情况。','供货商是否关门是方案中的不确定条件。')],M('If the clouds clear, the guide will go out; here if means that the guide will refuse to go regardless of the weather.','If the clouds clear, the guide will go out; here if introduces the condition for the plan.','if 引入计划成立的条件，并不表示不论天气如何都拒绝出发。'),[Q('if',1,1,'At the start of “If it rains, we will stay,” if means?','on the condition that it rains','although it never rains','a document showing identity','s1 引出条件。'),Q('if',2,2,'In “She asked if the shop was open,” if means?','whether the shop was open','because the shop was open','unless the shop was open','s2 引导间接疑问，意为是否。'),Q('if',3,3,'“Even if the train is late, we will wait” uses if to mean?','even though that condition may occur','only on the condition that it is early','a doubt about a person’s name','even if 表示即使。'),Q('if',4,4,'In “There is one if in the plan,” if is a noun meaning?','an uncertain possibility or condition','a statement known to be certain','a type of equation','s4 指尚不确定的条件或可能性。')]);
P('if not','If not 是由 if 与 not 组成的固定连接语，可表示“要不然、否则”，引出未采取前述行动时的替代结果。',C('if not.s1','建议与后果','Leave now, if not you may miss the last ferry across the bay.','现在就出发，否则你可能赶不上横渡海湾的末班渡船。','Leave now / if not you may miss the last ferry / across the bay.','if not 在此相当于 otherwise，承接前句建议并提出不照做的后果。','不马上出发就可能错过渡船，构成替代后果。'),M('“Leave now, if not you may miss the ferry” uses if not to mean that missing the ferry is impossible.','“Leave now, if not you may miss the ferry” warns that otherwise the ferry may be missed.','if not 引出不采取建议时可能发生的后果。'),[Q('if not',1,1,'In “Take a map, if not you may get lost,” if not means?','otherwise','because','even though','该短语表示否则。'),Q('if not',2,1,'Why does the speaker say “Leave now, if not…”?','to warn about a possible result of not leaving','to promise that no result can occur','to ask whether the listener has a passport','if not 引出不照做的后果。'),Q('if not',3,1,'Which phrase is closest in meaning to if not here?','otherwise','for example','as soon as','此处 if not 意为 otherwise。'),Q('if not',4,1,'“Bring an umbrella, if not you could get soaked” suggests?','without an umbrella, getting wet is possible','the umbrella guarantees rain','the listener is already dry indoors','后句说明不带伞的潜在结果。')]);
P('igloo','Igloo 经因纽特语 iglu“房屋”进入英语，常指因纽特猎人用压实积雪建成的圆顶冰雪屋。',C('igloo.s1','北极建筑','The guide explained how an Inuit hunter could cut blocks of compact snow and arrange them into a warm igloo.','向导讲解因纽特猎人如何切割压实的雪块，并把它们排列成保暖的圆顶雪屋。','The guide explained / how an Inuit hunter could cut blocks of compact snow / and arrange them into a warm igloo.','igloo 指用积雪建成的圆顶房屋；how 引出建造方式。','压实雪块搭成圆顶住所，符合 igloo 的词义。'),M('The hunter built an igloo from glass panels and heated bricks rather than packed snow.','The hunter built an igloo by arranging blocks of packed snow into a shelter.','用玻璃和砖建造的房屋不是此处所指的传统雪屋。'),[Q('igloo',1,1,'An igloo is traditionally a shelter made from?','blocks of packed snow','woven metal wire','dry leaves and paper','igloo 常由压实雪块搭成。'),Q('igloo',2,1,'What shape is commonly associated with an igloo?','a dome','a flat bridge','a tall open tower','圆顶是典型形状。'),Q('igloo',3,1,'The word igloo is associated with?','Inuit homes in Arctic regions','Roman algebra','a musical phrase','igloo 源自因纽特语的房屋词。'),Q('igloo',4,1,'Why might a guide demonstrate cutting snow blocks?','to explain how an igloo can be built','to show how to make an identity card','to identify a sea mammal','雪块可用于搭建冰雪屋。')]);
P('igneous','Igneous 来自拉丁语 igneus“火的”，地质学中形容由岩浆或熔岩冷却形成的火成岩。',C('igneous.s1','地质与岩石','The dark basalt was igneous rock formed when lava cooled quickly at the surface.','这种深色玄武岩是熔岩在地表迅速冷却后形成的火成岩。','The dark basalt was igneous rock / formed when lava cooled quickly / at the surface.','igneous 修饰 rock，指岩石由岩浆或熔岩冷却形成；formed 分词说明成因。','熔岩冷却生成玄武岩，符合火成岩定义。'),M('The geologist classified the fossil-rich limestone as igneous because it formed from layers of shells settling underwater.','The geologist classified basalt formed from cooled lava as igneous rock.','贝壳沉积形成的石灰岩属于沉积岩，而不是火成岩。'),[Q('igneous',1,1,'Igneous rock forms when?','magma or lava cools and solidifies','layers of shells compact underwater','wind piles loose sand into dunes','火成岩由岩浆或熔岩冷却形成。'),Q('igneous',2,1,'Basalt formed from cooled lava is?','igneous','a language idiom','a mathematical identity','玄武岩是常见火成岩。'),Q('igneous',3,1,'The root ign- in igneous is associated with?','fire','ice','identity','其词源与拉丁语“火”相关。'),Q('igneous',4,1,'Which process produces an igneous rock?','cooling molten material','cementing shells in layers','freezing a sweet dessert','熔融物质冷却形成火成岩。')]);
P('ignitable','Ignitable 由 ignite 加 -able 构成，表示遇到火花或火焰时能够着火的。',C('ignitable.s1','安全与材料','The safety label warned that the solvent was ignitable, so workers kept it away from sparks and open flames.','安全标签警告这种溶剂易燃，因此工人让它远离火花和明火。','The safety label warned / that the solvent was ignitable / so workers kept it away from sparks and open flames.','ignitable 作表语，表示物质能够着火；so 引出防范措施。','远离火花和明火是因为溶剂可以被点燃。'),M('The liquid was ignitable because tests showed it could not catch fire even when exposed to a flame.','The liquid was ignitable because a spark could make it catch fire.','完全不能着火的液体不符合 ignitable。','context'),[Q('ignitable',1,1,'An ignitable substance is able to?','catch fire when exposed to a spark or flame','put out every nearby fire','remain frozen at room temperature','ignitable 指可被点燃。'),Q('ignitable',2,1,'Why keep an ignitable solvent away from sparks?','a spark may start it burning','sparks make it turn into ice','it absorbs every flame safely','火花可能使易燃溶剂着火。'),Q('ignitable',3,1,'Which material is ignitable?','a liquid that catches fire from a small flame','a metal block that cannot burn','water used to extinguish a fire','能被小火焰点燃的液体符合含义。'),Q('ignitable',4,1,'The suffix -able in ignitable means?','capable of being ignited','already burned in the past','a person who lights a fire','-able 表示能够……的。')]);
P('ignite','Ignite 来自拉丁语 ignire“点燃”，可表示使物质着火、突然激起强烈情绪或冲突，也可指发动机点火启动。',[C('ignite.s1','火焰与材料','A single spark could ignite the dry grass beside the trail, so campers used the designated fire ring.','一颗火星就可能点燃小径旁的干草，因此露营者只在指定火圈生火。','A single spark could ignite the dry grass / beside the trail / so campers used the designated fire ring.','ignite 表示使物体开始燃烧；so 说明采取安全措施的原因。','火星能够使干草着火。'),C('ignite.s2','情绪与冲突','The unfair rule ignited anger among the tenants, who organized a meeting to ask for an explanation.','这条不公平的规定激起租户的愤怒，他们组织会议要求解释。','The unfair rule ignited anger among the tenants / who organized a meeting / to ask for an explanation.','ignite 可比喻突然引发强烈情绪；who 从句补充租户后续行动。','不公平规则突然引起愤怒。'),C('ignite.s3','发动机与机械','The mechanic turned the key to ignite the engine, then listened for the regular sound of combustion.','技师转动钥匙启动发动机，接着聆听燃烧是否规律。','The mechanic turned the key / to ignite the engine / then listened for the regular sound of combustion.','ignite the engine 指使发动机点火启动；to 表示转动钥匙的目的。','点火后检查发动机燃烧声。')],M('The spark ignited the dry grass even though it made the grass permanently wet and cold.','The spark ignited the dry grass by starting it burning.','点燃会使干草开始燃烧，不会使它变湿变冷。'),[Q('ignite',1,1,'To ignite dry wood is to?','make it start burning','identify its owner','make it stop producing heat','s1 表示点燃。'),Q('ignite',2,2,'A speech may ignite public anger when it?','suddenly causes strong feelings','calms every disagreement','identifies a speaker’s name','s2 表示激起强烈情绪。'),Q('ignite',3,3,'A mechanic ignites an engine to?','start combustion in it','turn it into an igloo','make it idle forever','s3 指发动机点火启动。'),Q('ignite',4,1,'Which event could ignite a fire?','a spark landing on dry grass','rain soaking the grass','a fire extinguisher being opened','火星可能点燃干草。')]);
P('igniter','Igniter 由 ignite 加表示器具或执行者的后缀 -er 构成，指在发动机、加热器或点火装置中启动燃烧的部件。',C('igniter.s1','设备与维修','The technician replaced the heater’s igniter after the burner failed to light despite a steady fuel supply.','燃料供应正常但燃烧器仍无法点燃，技师于是更换了加热器的点火装置。','The technician replaced the heater’s igniter / after the burner failed to light / despite a steady fuel supply.','igniter 指负责启动燃烧的部件；after 引出维修原因。','更换点火部件后才能让燃烧器启动。'),M('The heater’s igniter was the fuel tank because it stored fuel but never produced a spark or started combustion.','The heater’s igniter was the component that produced the spark to start combustion.','燃料箱储存燃料而非执行点火。','context'),[Q('igniter',1,1,'An igniter in a heater helps?','start combustion','measure room humidity','store user identification','点火装置负责启动燃烧。'),Q('igniter',2,1,'Why replace an igniter if a burner will not light?','it may no longer start the fuel burning','it determines the heater’s color','it keeps the room from having any air','点火装置失效可能导致燃烧器无法着火。'),Q('igniter',3,1,'An igniter is usually?','a component in a device','a feeling of public disgrace','a word for a quiet landscape','它是设备中的部件。'),Q('igniter',4,1,'The suffix -er in igniter names?','a device or part that performs an action','a condition of not knowing','a person’s cultural identity','-er 可指执行点火作用的部件。')]);
P('ignition','Ignition 来自 ignite 加 -ion，可指开始燃烧的点火过程，也可指汽车发动机的电气点火系统。',[C('ignition.s1','燃烧过程','The ignition of the gas occurred only after the pilot flame reached the burner, and the room then warmed steadily.','只有在引火焰触及燃烧器后，燃气才被点燃，房间随后逐渐暖和起来。','The ignition of the gas occurred / only after the pilot flame reached the burner / and the room then warmed steadily.','ignition 指使某物开始燃烧的过程；only after 强调点火发生的条件。','引火焰触发燃气燃烧体现点燃过程义。'),C('ignition.s2','汽车与启动','A warning light appeared when the driver turned the key, so a mechanic inspected the car’s ignition system.','司机转动钥匙时警示灯亮起，因此技师检查了汽车的点火系统。','A warning light appeared / when the driver turned the key / so a mechanic inspected the car’s ignition system.','ignition system 指启动汽车发动机的电气系统；so 引出检查原因。','故障发生在钥匙启动时，指汽车点火系统。')],M('The car’s ignition system was the windshield because it protected the engine from rain but did not start it.','The car’s ignition system supplied the electrical spark needed to start the engine.','挡风玻璃并不负责发动机点火。','context'),[Q('ignition',1,1,'Ignition of a fuel is?','the process of making it start burning','the process of cooling it into rock','a system for identifying a driver','s1 指燃烧开始的过程。'),Q('ignition',2,2,'A vehicle’s ignition system helps?','start the engine','measure the fuel’s color','keep the windshield clean','s2 指汽车发动机点火系统。'),Q('ignition',3,1,'What can trigger ignition of gas in a burner?','a pilot flame','a passport check','a quiet path','引火焰可以点燃燃气。'),Q('ignition',4,2,'If a mechanic checks the ignition after the key is turned, the mechanic checks?','the system that starts the engine','the car’s identity document','the system that cools lava','发动机启动系统就是汽车点火系统。')]);
P('ignitor','Ignitor 是 ignite 的变体拼写加名词后缀 -or，指点燃燃料或引爆装药的点火器部件。',C('ignitor.s1','机械与燃烧','The test rig would not start until engineers replaced the faulty ignitor that was supposed to light the fuel mixture.','工程师更换了负责点燃燃料混合物的故障点火器后，试验装置才启动。','The test rig would not start / until engineers replaced the faulty ignitor / that was supposed to light the fuel mixture.','ignitor 指使燃料着火的部件；until 表示更换前装置无法启动。','该部件负责点燃燃料混合物。','ignitor 是 igniter 的变体拼写；本文保留词头原拼写。'),M('The faulty ignitor stopped the test rig because its only function was to extinguish the fuel before combustion.','The faulty ignitor stopped the test rig because it could no longer light the fuel mixture.','点火器负责点燃燃料，而不是将其熄灭。','context'),[Q('ignitor',1,1,'An ignitor is a component that?','ignites fuel or an explosive charge','cools molten rock into stone','proves a passenger’s identity','ignitor 是负责点燃燃料或装药的部件。'),Q('ignitor',2,1,'Why might a faulty ignitor stop a burner from starting?','it may fail to light the fuel','it may make the fuel colder than ice','it may identify the burner’s owner','缺少点火会使燃烧器无法启动。'),Q('ignitor',3,1,'Ignitor is a variant spelling related to?','ignite','idiom','identity','ignitor 与 ignite 同源。'),Q('ignitor',4,1,'Which part could be called an ignitor?','a device that sparks to light a fuel mixture','a sensor that only reads room temperature','a label listing a machine’s owner','点燃燃料混合物的装置可称 ignitor。')]);
P('ignoble','Ignoble 来自拉丁语 ignobilis，由 in-“不”与 nobilis“高贵的”构成，形容道德卑劣或令人不名誉的。',C('ignoble.s1','道德选择','The captain rejected the ignoble plan to blame an innocent deckhand for the crew’s own mistake.','船长拒绝了把船员自身过失栽到无辜水手身上的卑劣计划。','The captain rejected the ignoble plan / to blame an innocent deckhand / for the crew’s own mistake.','ignoble 修饰 plan，表示道德上卑劣；to blame 说明计划内容。','诬陷无辜者是卑劣行为。'),M('Blaming an innocent worker for one’s own mistake was an ignoble act of honesty and fairness.','Blaming an innocent worker for one’s own mistake was ignoble and unfair.','诬陷无辜者并不诚实或公平。'),[Q('ignoble',1,1,'An ignoble act is?','morally low or shameful','generous and honorable','a process of starting a fire','ignoble 表示卑劣、不名誉。'),Q('ignoble',2,1,'Why was blaming an innocent deckhand ignoble?','it unfairly shifted blame onto someone who did not cause the mistake','it rewarded the person who caused the mistake','it corrected the record honestly','栽赃无辜者是道德上卑劣的。'),Q('ignoble',3,1,'Which choice is ignoble?','taking credit for another person’s work','admitting one’s own mistake','helping a stranger without reward','冒领他人功劳不光彩。'),Q('ignoble',4,1,'Ignoble is closest to?','shameful','idyllic','identical','ignoble 与 shameful 意思相近。')]);
P('ignominious','Ignominious 经拉丁语 ignominiosus 派生自 ignominia“耻辱”，形容使人蒙受深重公开羞耻或名誉受损的。',C('ignominious.s1','声誉与失败','The team suffered an ignominious defeat when it conceded six goals without scoring once in the final.','这支队伍在决赛中一球未进却连失六球，遭遇了一场可耻的惨败。','The team suffered an ignominious defeat / when it conceded six goals / without scoring once in the final.','ignominious 修饰 defeat，强调失败带来公开羞辱；when 从句交代原因。','悬殊失利让球队蒙受名誉上的难堪。'),M('The team’s ignominious defeat brought no embarrassment because it won decisively and received public praise.','The team’s ignominious defeat was humiliating because it lost by a wide margin in public.','大胜并受赞扬不构成可耻的失败。'),[Q('ignominious',1,1,'An ignominious defeat is one that is?','deeply humiliating or disgraceful','quietly successful and celebrated','caused by a small harmless delay','ignominious 描写可耻、丢脸的失败。'),Q('ignominious',2,1,'Why was the team’s loss ignominious?','the public saw a lopsided defeat','the team won the final comfortably','nobody knew the game had happened','公开悬殊失利使人蒙羞。'),Q('ignominious',3,1,'Ignominious is often used for an outcome that damages?','a person’s or group’s honor','a machine’s fuel supply','a phrase’s grammar','它形容损害名誉的结果。'),Q('ignominious',4,1,'Which is an ignominious outcome?','a public defeat that leaves the team disgraced','a quiet practice session that improves skill','a fair victory after close competition','公开受辱的失败符合该词。')]);
P('ignominy','Ignominy 经拉丁语 ignominia 而来，指公开丧失名誉、蒙受奇耻大辱的处境或经历。',C('ignominy.s1','名誉与丑闻','The official resigned in ignominy after an inquiry revealed that he had falsified the public accounts.','调查揭露这名官员伪造公共账目后，他在耻辱中辞职。','The official resigned in ignominy / after an inquiry revealed / that he had falsified the public accounts.','in ignominy 表示在公开耻辱中；after 引出丢尽名誉的原因。','公开查出的舞弊使官员蒙受耻辱。'),M('The official left office in ignominy after being honored publicly for transparent and honest service.','The official left office in ignominy after the inquiry exposed his public fraud.','因诚实服务获公开表彰并非蒙受耻辱。'),[Q('ignominy',1,1,'Ignominy is?','public loss of honor or deep disgrace','a calm and pleasant scene','the act of identifying an object','ignominy 指奇耻大辱。'),Q('ignominy',2,1,'An official might face ignominy after?','a public inquiry exposes serious misconduct','a routine meeting ends on time','a festival receives good weather','公开揭露严重失当会带来耻辱。'),Q('ignominy',3,1,'To leave office in ignominy is to leave?','under deep public disgrace','after a private promotion','without anyone knowing one’s name','该表达指蒙羞离职。'),Q('ignominy',4,1,'Ignominy is closely related to which adjective?','ignominious','ignitable','idyllic','ignominious 描写带来耻辱的事。')]);
P('ignorance','Ignorance 来自拉丁语 ignorantia，指对某主题缺乏知识或信息，也可指普遍不知情的状态。',[C('ignorance.s1','教育与信息','The workshop addressed ignorance of local water rules by explaining where residents could find reliable guidance.','研讨会讲解居民如何查找可靠指南，以弥补他们对当地用水规定的不了解。','The workshop addressed ignorance of local water rules / by explaining / where residents could find reliable guidance.','ignorance of 表示对某事缺乏了解；by 引出减少这种缺乏的方式。','居民欠缺当地规定的信息，说明知识不足。'),C('ignorance.s2','常识与社会','The campaign targeted public ignorance about carbon monoxide by teaching families to recognize the alarm and leave the house.','这项宣传通过教家庭成员识别一氧化碳警报并离开房屋，来减少公众对这种危险的无知。','The campaign targeted public ignorance about carbon monoxide / by teaching families / to recognize the alarm and leave the house.','public ignorance 指公众普遍不知情；by 引出宣传教育方法。','公众需要学习识别警报，表明此前缺乏常识。')],M('The workshop addressed ignorance of the water rules even though every resident already knew and understood them fully.','The workshop addressed ignorance of the water rules among residents who lacked reliable information.','已经充分了解规定的人并非处于无知状态。'),[Q('ignorance',1,1,'Ignorance of a subject is?','a lack of knowledge or information about it','proof that a person has mastered it','a feeling of belonging to a group','s1 指对某主题缺乏知识。'),Q('ignorance',2,2,'Public ignorance about a safety alarm means?','many people do not know how it works','everyone has practiced using it','the alarm has no sound','s2 指公众普遍不知情。'),Q('ignorance',3,1,'A workshop can reduce ignorance by?','providing reliable information','hiding every useful instruction','removing the alarm from homes','教育与可靠信息能弥补知识不足。'),Q('ignorance',4,2,'Which situation shows ignorance of a safety rule?','residents do not know what the warning signal means','residents correctly follow the signal','residents teach the rule to others','不了解警报含义体现无知。')]);
P('ignorant','Ignorant 来自拉丁语 ignorans，形容缺乏某主题的知识；也可批评无礼或显得缺乏教养的行为。',[C('ignorant.s1','知识与学习','I was ignorant of the permit requirement, so the clerk showed me the official page before I submitted the application.','我当时不知道许可要求，因此办事员在我提交申请前给我看了官方页面。','I was ignorant of the permit requirement / so the clerk showed me the official page / before I submitted the application.','ignorant of 表示不了解某事；so 引出提供资料的原因。','说话者原本不知道许可要求，体现知识不足义。'),C('ignorant.s2','礼貌与沟通','The moderator called the remark ignorant because it mocked a community without checking even basic facts.','主持人批评那番话既无知又失礼，因为它未经核实基本事实就嘲笑一个群体。','The moderator called the remark ignorant / because it mocked a community / without checking even basic facts.','ignorant 可批评表现出无知或不礼貌；because 引出原因。','未经了解就嘲笑他人，兼有无知和失礼。'),C('ignorant.s3','社交礼仪','Cutting into the queue and shouting at the clerk was ignorant behavior, though the visitor later apologized.','插队并对办事员大喊是失礼的行为，不过那位访客后来道了歉。','Cutting into the queue and shouting at the clerk / was ignorant behavior / though the visitor later apologized.','ignorant 在口语中可指不懂规矩、失礼；though 引出后来道歉。','插队和大喊表现出不懂礼貌。')],M('The comment was ignorant because it carefully checked the facts and treated the community with respect.','The comment was ignorant because it mocked a community without checking basic facts.','核实事实并尊重他人不符合该语境中的 ignorant。'),[Q('ignorant',1,1,'Someone ignorant of a rule?','does not know or understand that rule','has memorized every detail of it','has a strong sense of group identity','s1 指不了解某事。'),Q('ignorant',2,2,'An ignorant remark may be one that?','shows poor knowledge and mocks others unfairly','carefully checks facts before speaking','politely asks for more information','s2 可批评无知且冒犯人的言论。'),Q('ignorant',3,3,'In informal use, ignorant behavior can be?','rude or lacking basic manners','a perfectly natural idiom','a type of igneous rock','s3 指失礼、不懂规矩。'),Q('ignorant',4,1,'Which phrase is grammatical?','ignorant of the permit requirement','ignorant the permit requirement of','ignorant with the permit requirement','常用搭配是 ignorant of。')]);
P('ignore','Ignore 经古法语 ignorer 源自拉丁语 ignorare“不知道”，现代英语中表示不予理会、假装没看见某人，或有意不考虑某事。',[C('ignore.s1','警示与注意','The driver ignored the dashboard warning and continued until the engine began to overheat.','司机无视仪表盘警告继续行驶，直到发动机开始过热。','The driver ignored the dashboard warning / and continued / until the engine began to overheat.','ignore 表示不理会警示；and 连接无视警告后的行动。','司机没有理会仪表警告。'),C('ignore.s2','社交互动','At the reunion, Leon ignored his former teammate by looking away and walking past without greeting him.','聚会上，利昂移开视线，经过前队友身边时没有打招呼，假装没看见他。','At the reunion / Leon ignored his former teammate / by looking away and walking past without greeting him.','ignore someone 可指假装没看见或不理某人；by 引出做法。','刻意不看也不打招呼体现社交上的不理会。'),C('ignore.s3','分析与决策','The report cannot ignore repair costs when comparing the two machines, even if their purchase prices are similar.','比较两台机器时，报告不能不考虑维修费用，即使它们的购买价格相近。','The report cannot ignore repair costs / when comparing the two machines / even if their purchase prices are similar.','ignore 可指有意不予考虑；cannot 表示比较时必须考虑该因素。','维修费用必须纳入比较。')],M('The driver ignored the warning by stopping immediately and following its instructions.','The driver followed the warning rather than ignoring it.','遵循警告与无视警告相反。'),[Q('ignore',1,1,'To ignore a warning is to?','pay no attention to it','follow it immediately','write it in a diary','s1 指不理会。'),Q('ignore',2,2,'At a reunion, Leon ignored his former teammate when he?','pretended not to see him and walked past','greeted him warmly','introduced him to the group','s2 指假装不认识某人。'),Q('ignore',3,3,'A report ignores a cost when it?','deliberately leaves that cost out of consideration','calculates the cost carefully','adds the cost to the comparison','s3 指不予考虑。'),Q('ignore',4,1,'Which action is the opposite of ignoring an alarm?','responding to it and following its instructions','turning away and pretending not to hear it','covering it so nobody can notice','回应警报与无视警报相反。')]);
P('ill','Ill 可能源自古诺尔斯语 illr“坏的”，可作形容词表示生病或有害、恶意，也可作副词表示恶劣或不充分，或作名词指疾病、社会弊端。',[C('ill.s1','健康与休息','Nora stayed home because she felt ill and had a fever that made it difficult to concentrate.','诺拉因为感觉不适且发烧而留在家中，发烧让她难以集中注意力。','Nora stayed home / because she felt ill / and had a fever that made it difficult to concentrate.','ill 作形容词表示身体不适；because 引出留在家的原因。','发烧和不适体现生病义。'),C('ill.s2','伤害与后果','The chemical spill had an ill effect on the wetland, killing fish and damaging the reeds along the bank.','化学品泄漏对湿地产生有害影响，导致鱼类死亡并破坏岸边的芦苇。','The chemical spill had an ill effect on the wetland / killing fish / and damaging the reeds along the bank.','ill 修饰 effect，表示不良、有害；后两个分词短语列出影响。','鱼类死亡和芦苇受损说明影响有害。'),C('ill.s3','表达与能力','The newly hired interpreter spoke ill of the technical terms and asked a colleague to clarify them before the meeting.','新聘译员对技术术语掌握得不充分，因此在会议前请同事解释。','The newly hired interpreter spoke ill of the technical terms / and asked a colleague / to clarify them before the meeting.','此处按 registry 的副词义理解 ill 为“能力不足地、不充分地”；and 连接其请求。','需要同事补充解释体现对术语掌握不足。'),C('ill.s4','疾病与记录','The public-health report lists asthma among the common ills treated at the clinic.','公共卫生报告把哮喘列为诊所治疗的常见疾病之一。','The public-health report lists asthma / among the common ills / treated at the clinic.','ill 作名词复数 ills，指疾病；among 引出疾病类别。','哮喘被列为一种疾病。'),C('ill.s5','社会问题','The commission studied the ills of overcrowded housing, including poor ventilation and unsafe wiring.','委员会研究拥挤住房带来的弊端，包括通风不良和线路不安全。','The commission studied the ills of overcrowded housing / including poor ventilation / and unsafe wiring.','ills 作名词，指社会中的弊端或问题；including 列举问题。','通风和线路问题是拥挤住房带来的弊端。')],M('The chemical had an ill effect on the wetland because it improved water quality and restored every damaged habitat.','The chemical had a harmful effect on the wetland because it killed fish and damaged plants.','修复栖地属于有益效果，不是 ill effect。'),[Q('ill',1,1,'A person who feels ill is?','unwell or not in good health','especially suitable for a purpose','a person’s admired hero','s1 表示身体不适。'),Q('ill',2,2,'An ill effect is?','a harmful or bad result','a guaranteed improvement','an uncertain possibility only','s2 表示有害影响。'),Q('ill',3,3,'If someone performs a task ill, they perform it?','badly or with difficulty','in perfect health','as a mathematical identity','s3 是副词，表示做得不好或有困难。'),Q('ill',4,5,'The ills of overcrowded housing are?','problems such as poor ventilation and unsafe wiring','all the healthy features of a home','official documents proving identity','s5 指社会弊端或问题。')]);
P('ill luck','Ill luck 是 ill“坏的”与 luck“运气”的组合，指厄运或不走运的情况。',C('ill luck.s1','意外与运气','Through ill luck, the hikers reached the pass just as a sudden storm closed the trail.','徒步者运气不佳，刚到山口，突如其来的暴风雨就封住了道路。','Through ill luck / the hikers reached the pass / just as a sudden storm closed the trail.','ill luck 是名词短语，作介词 through 的宾语，表示坏运气；just as 标出不巧的时刻。','暴风雨恰好封路，属于不走运的遭遇。'),M('The hikers had ill luck when perfect weather and an open trail made their crossing easy.','The hikers had ill luck when a storm closed the trail at the moment they arrived.','天气理想、道路畅通是好运而非厄运。'),[Q('ill luck',1,1,'Ill luck means?','bad fortune','a useful safety device','a feeling of cultural belonging','该词组意为厄运。'),Q('ill luck',2,1,'Why did the hikers experience ill luck?','a storm closed the trail just as they arrived','the path stayed clear in perfect weather','they found a warm shelter nearby','暴风雨赶在抵达时封路，属于厄运。'),Q('ill luck',3,1,'Which event is an example of ill luck?','missing a train because an unexpected road closure delayed the bus','catching an earlier train than expected','finding the lost keys in a pocket','意外延误导致错过列车是不走运。'),Q('ill luck',4,1,'Ill in ill luck means?','bad or unfortunate','healthy and well','identical in every detail','ill 在词组中表示坏的。')]);
P('ill will','Ill will 是 ill“坏的”与 will“意愿、心意”的组合，指对他人的恶意或敌意。',C('ill will.s1','人际关系','Despite their disagreement about the project, Asha bore no ill will toward her colleague and helped review his draft.','尽管两人对项目有分歧，阿莎并不怨恨同事，还帮他审阅草稿。','Despite their disagreement about the project / Asha bore no ill will toward her colleague / and helped review his draft.','bear ill will toward someone 表示对某人怀有恶意；despite 引出与此相反的争执。','她虽有分歧仍愿意帮助同事，说明没有敌意。'),M('Asha bore ill will toward her colleague, so she supported him warmly and wished him success.','Asha bore no ill will toward her colleague; she remained willing to help him.','积极支持和帮助同事说明没有怀有恶意。'),[Q('ill will',1,1,'Ill will toward someone means?','bad or hostile feelings toward that person','a wish to help that person','a lack of information about a topic','ill will 指恶意或敌意。'),Q('ill will',2,1,'A person who bears no ill will toward a colleague?','does not feel hostility toward them','secretly hopes they fail','refuses to recognize their identity','no ill will 表示没有恶意。'),Q('ill will',3,1,'Which action suggests ill will?','deliberately spreading a false rumor to harm someone','offering fair feedback on a draft','helping a colleague prepare for a meeting','故意散布谣言伤害他人体现恶意。'),Q('ill will',4,1,'Ill will is closest in meaning to?','hostility','good fortune','identification','ill will 与 hostility 意思相近。')]);
P('ill-equipped','Ill-equipped 由 ill“欠佳”与 equipped“配备、准备好”构成，形容缺少完成任务所需的器材或能力。',C('ill-equipped.s1','准备与任务','The rescue crew was ill-equipped for a winter climb because it lacked insulated ropes, spare batteries, and warm shelter.','救援队缺少保温绳索、备用电池和温暖庇护所，不具备冬季攀登所需的装备。','The rescue crew was ill-equipped for a winter climb / because it lacked insulated ropes, spare batteries, and warm shelter.','ill-equipped 作表语，表示装备或能力不足；because 列出缺少的必要物品。','缺少冬季攀登所需装备，说明准备不足。','连字符复合形容词保留 manifest 拼写 ill-equipped。'),M('The rescue crew was ill-equipped because it carried every required tool, warm shelter, and spare battery.','The rescue crew was ill-equipped because it lacked essential winter-climbing gear.','具备所有必要装备不属于准备不足。','context'),[Q('ill-equipped',1,1,'An ill-equipped team?','lacks equipment or ability needed for its task','has every tool and skill required','is unwell but otherwise fully prepared','该词指缺少装备或能力。'),Q('ill-equipped',2,1,'Why was the rescue crew ill-equipped for winter climbing?','it lacked insulated ropes and warm shelter','it carried all required gear','the weather was mild and the route was closed','队伍缺少必要冬季装备。'),Q('ill-equipped',3,1,'Which person is ill-equipped for a task?','a trainee sent to repair wiring without tools or training','a trained electrician with a full toolkit','a guide carrying all needed safety gear','没有工具和训练的人准备不足。'),Q('ill-equipped',4,1,'The prefix ill- in ill-equipped means?','badly or inadequately','in a healthy condition','completely identical','ill- 在这里表示欠佳或不足。')]);

})();
